export declare const EMBEDDED_ADMIN_HTML = "<!DOCTYPE html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>\u0644\u0648\u062D\u0629 \u0627\u0644\u062A\u062D\u0643\u0645 \u0627\u0644\u0625\u062F\u0627\u0631\u064A\u0629 \u0627\u0644\u0645\u062A\u0643\u0627\u0645\u0644\u0629 | \u0645\u062A\u062C\u0631 \u0632\u0647\u0631\u0629 (Zahra Store)</title>\n  <!-- Google Fonts: Cairo -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n  <link href=\"https://fonts.googleapis.com/css2?family=Cairo:wght@300;400;500;600;700;800;900&display=swap\" rel=\"stylesheet\" />\n  <!-- Tailwind CSS CDN -->\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <!-- Font Awesome Icons -->\n  <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\" />\n  <!-- Chart.js CDN -->\n  <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n\n  <script>\n    tailwind.config = {\n      darkMode: 'class',\n      theme: {\n        extend: {\n          colors: {\n            brand: {\n              50: '#fdf2f8',\n              100: '#fce7f3',\n              200: '#fbcfe8',\n              300: '#f9a8d4',\n              400: '#f472b6',\n              500: '#ec4899',\n              600: '#db2777',\n              700: '#be185d',\n              800: '#9d174d',\n              900: '#831843',\n            },\n          },\n          fontFamily: {\n            cairo: ['Cairo', 'sans-serif'],\n          }\n        }\n      }\n    }\n  </script>\n  <style>\n    body { font-family: 'Cairo', sans-serif; }\n    .custom-scrollbar::-webkit-scrollbar { width: 6px; height: 6px; }\n    .custom-scrollbar::-webkit-scrollbar-track { background: #f8fafc; }\n    .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 4px; }\n    .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #94a3b8; }\n  </style>\n</head>\n<body class=\"bg-slate-50 text-slate-800 antialiased min-h-screen flex flex-col\">\n\n  <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 LOGIN OVERLAY (when unauthenticated) \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n  <div id=\"loginScreen\" class=\"fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[100] flex items-center justify-center p-4 hidden\">\n    <div class=\"bg-white rounded-3xl max-w-md w-full p-8 shadow-2xl border border-slate-100 text-right space-y-6\">\n      <div class=\"text-center space-y-2\">\n        <div class=\"w-16 h-16 rounded-2xl bg-gradient-to-tr from-brand-700 to-brand-500 mx-auto flex items-center justify-center text-white text-3xl shadow-lg shadow-brand-500/30\">\n          <i class=\"fa-solid fa-spa\"></i>\n        </div>\n        <h2 class=\"text-xl font-black text-slate-900\">\u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u062F\u062E\u0648\u0644 \u0625\u0644\u0649 \u0644\u0648\u062D\u0629 \u0627\u0644\u062A\u062D\u0643\u0645</h2>\n        <p class=\"text-xs text-slate-500\">\u0645\u062A\u062C\u0631 \u0632\u0647\u0631\u0629 \u0644\u0644\u0645\u0641\u0631\u0648\u0634\u0627\u062A \u0648\u062A\u0644\u0628\u064A\u0633\u0627\u062A \u0627\u0644\u0643\u0631\u0627\u0633\u064A (Supabase & NestJS)</p>\n      </div>\n\n      <form onsubmit=\"handleLoginSubmit(event)\" class=\"space-y-4 text-xs\">\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0644\u0628\u0631\u064A\u062F \u0627\u0644\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A</label>\n          <div class=\"relative\">\n            <input type=\"email\" id=\"loginEmail\" required value=\"admin@zahra-store.com\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl py-3 px-3 pl-10 focus:border-brand-500 focus:outline-none font-medium\" />\n            <i class=\"fa-solid fa-envelope absolute left-3 top-3.5 text-slate-400\"></i>\n          </div>\n        </div>\n\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631</label>\n          <div class=\"relative\">\n            <input type=\"password\" id=\"loginPassword\" required value=\"admin123456\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl py-3 px-3 pl-10 focus:border-brand-500 focus:outline-none font-medium\" />\n            <i class=\"fa-solid fa-lock absolute left-3 top-3.5 text-slate-400\"></i>\n          </div>\n        </div>\n\n        <button type=\"submit\" id=\"loginSubmitBtn\" class=\"w-full py-3 bg-brand-600 hover:bg-brand-700 text-white rounded-xl font-bold text-sm shadow-md shadow-brand-600/20 transition-all flex items-center justify-center gap-2\">\n          <span>\u062F\u062E\u0648\u0644 \u0644\u0648\u062D\u0629 \u0627\u0644\u062A\u062D\u0643\u0645</span>\n          <i class=\"fa-solid fa-arrow-left\"></i>\n        </button>\n\n        <div class=\"bg-brand-50 p-3 rounded-xl border border-brand-100 text-[11px] text-brand-800 space-y-1\">\n          <div class=\"font-bold\">\uD83D\uDD11 \u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u062F\u062E\u0648\u0644 \u0627\u0644\u0627\u0641\u062A\u0631\u0627\u0636\u064A\u0629 \u0644\u0644\u0645\u062F\u064A\u0631:</div>\n          <div>\u0627\u0644\u0628\u0631\u064A\u062F: <span class=\"font-mono font-semibold\">admin@zahra-store.com</span></div>\n          <div>\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631: <span class=\"font-mono font-semibold\">admin123456</span></div>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 TOP NAVIGATION BAR \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n  <header class=\"bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm\">\n    <div class=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between\">\n      <div class=\"flex items-center gap-3\">\n        <div class=\"w-10 h-10 rounded-xl bg-gradient-to-tr from-brand-700 to-brand-500 flex items-center justify-center text-white shadow-md shadow-brand-500/20\">\n          <i class=\"fa-solid fa-spa text-xl\"></i>\n        </div>\n        <div>\n          <h1 class=\"text-lg font-bold text-slate-900 leading-none\">\u0645\u062A\u062C\u0631 \u0632\u0647\u0631\u0629</h1>\n          <span class=\"text-xs text-brand-600 font-medium\">\u0644\u0648\u062D\u0629 \u0627\u0644\u062A\u062D\u0643\u0645 \u0648\u0627\u0644\u0625\u062F\u0627\u0631\u0629 \u0627\u0644\u0645\u0627\u0644\u064A\u0629 \u0648\u0627\u0644\u0633\u062D\u0627\u0628\u064A\u0629 (Supabase)</span>\n        </div>\n      </div>\n\n      <div class=\"flex items-center gap-3\">\n        <button onclick=\"refreshCurrentTab()\" class=\"p-2 text-slate-500 hover:text-brand-600 hover:bg-slate-100 rounded-lg transition-colors\" title=\"\u062A\u062D\u062F\u064A\u062B \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A\">\n          <i class=\"fa-solid fa-arrows-rotate\"></i>\n        </button>\n        <a href=\"/api/docs\" target=\"_blank\" class=\"hidden sm:inline-flex items-center gap-2 px-3 py-1.5 text-xs font-semibold text-slate-600 hover:text-brand-600 bg-slate-100 hover:bg-brand-50 border border-slate-200 rounded-lg transition-colors\">\n          <i class=\"fa-solid fa-book text-brand-500\"></i>\n          <span>\u062A\u0648\u062B\u064A\u0642 Swagger</span>\n        </a>\n        <a href=\"http://localhost:3000\" target=\"_blank\" class=\"hidden sm:inline-flex items-center gap-2 px-3 py-1.5 text-xs font-semibold text-slate-600 hover:text-brand-600 bg-slate-100 hover:bg-brand-50 border border-slate-200 rounded-lg transition-colors\">\n          <i class=\"fa-solid fa-store text-emerald-500\"></i>\n          <span>\u0627\u0644\u0645\u062A\u062C\u0631</span>\n        </a>\n        \n        <div class=\"h-6 w-px bg-slate-200 hidden sm:block\"></div>\n\n        <div class=\"flex items-center gap-3\">\n          <div class=\"w-9 h-9 rounded-full bg-brand-100 text-brand-700 font-bold flex items-center justify-center text-sm border border-brand-200\" id=\"userAvatar\">\n            \u0645\n          </div>\n          <div class=\"hidden md:block text-right\">\n            <div class=\"text-xs font-bold text-slate-800\" id=\"userNameDisplay\">\u0645\u062F\u064A\u0631 \u0645\u062A\u062C\u0631 \u0632\u0647\u0631\u0629</div>\n            <div class=\"text-[10px] text-emerald-600 font-medium flex items-center gap-1\" id=\"userRoleBadge\">\n              <span class=\"w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse\"></span>\n              \u0645\u062F\u064A\u0631 \u0639\u0627\u0645 (ADMIN)\n            </div>\n          </div>\n          <button onclick=\"handleLogout()\" title=\"\u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u062E\u0631\u0648\u062C \u0627\u0644\u0641\u0639\u0644\u064A\" class=\"text-slate-400 hover:text-rose-600 p-2 rounded-lg hover:bg-rose-50 transition-colors flex items-center gap-1 text-xs font-bold\">\n            <i class=\"fa-solid fa-arrow-right-from-bracket text-sm\"></i>\n            <span class=\"hidden sm:inline\">\u062E\u0631\u0648\u062C</span>\n          </button>\n        </div>\n      </div>\n    </div>\n  </header>\n\n  <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 MAIN LAYOUT \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n  <div class=\"flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 flex flex-col md:flex-row gap-6\">\n\n    <!-- Sidebar Navigation -->\n    <aside class=\"w-full md:w-64 shrink-0\">\n      <nav class=\"bg-white rounded-2xl border border-slate-200 p-2 shadow-sm space-y-1 sticky top-22\">\n        <button onclick=\"switchTab('overview')\" id=\"tab-btn-overview\" class=\"w-full flex items-center justify-between px-3 py-2.5 rounded-xl font-medium text-sm transition-all text-brand-700 bg-brand-50\">\n          <div class=\"flex items-center gap-3\">\n            <i class=\"fa-solid fa-chart-pie w-5 text-center text-brand-600\"></i>\n            <span>\u0646\u0638\u0631\u0629 \u0639\u0627\u0645\u0629 \u0648\u0623\u0631\u0628\u0627\u062D</span>\n          </div>\n        </button>\n\n        <button onclick=\"switchTab('products')\" id=\"tab-btn-products\" class=\"w-full flex items-center justify-between px-3 py-2.5 rounded-xl font-medium text-sm transition-all text-slate-600 hover:bg-slate-50\">\n          <div class=\"flex items-center gap-3\">\n            <i class=\"fa-solid fa-tags w-5 text-center text-slate-400\"></i>\n            <span>\u0625\u062F\u0627\u0631\u0629 \u0627\u0644\u0645\u0646\u062A\u062C\u0627\u062A</span>\n          </div>\n          <span id=\"badge-products-count\" class=\"bg-slate-100 text-slate-600 text-[11px] font-bold px-2 py-0.5 rounded-full\">0</span>\n        </button>\n\n        <button onclick=\"switchTab('categories')\" id=\"tab-btn-categories\" class=\"w-full flex items-center justify-between px-3 py-2.5 rounded-xl font-medium text-sm transition-all text-slate-600 hover:bg-slate-50\">\n          <div class=\"flex items-center gap-3\">\n            <i class=\"fa-solid fa-folder-tree w-5 text-center text-slate-400\"></i>\n            <span>\u0627\u0644\u0623\u0642\u0633\u0627\u0645 \u0648\u0627\u0644\u062A\u0635\u0646\u064A\u0641\u0627\u062A</span>\n          </div>\n          <span id=\"badge-categories-count\" class=\"bg-slate-100 text-slate-600 text-[11px] font-bold px-2 py-0.5 rounded-full\">0</span>\n        </button>\n\n        <button onclick=\"switchTab('orders')\" id=\"tab-btn-orders\" class=\"w-full flex items-center justify-between px-3 py-2.5 rounded-xl font-medium text-sm transition-all text-slate-600 hover:bg-slate-50\">\n          <div class=\"flex items-center gap-3\">\n            <i class=\"fa-solid fa-box-archive w-5 text-center text-slate-400\"></i>\n            <span>\u0625\u062F\u0627\u0631\u0629 \u0627\u0644\u0637\u0644\u0628\u0627\u062A</span>\n          </div>\n          <span id=\"badge-pending-orders\" class=\"bg-amber-100 text-amber-800 text-[11px] font-bold px-2 py-0.5 rounded-full hidden\">0</span>\n        </button>\n\n        <button onclick=\"switchTab('custom-chairs')\" id=\"tab-btn-custom-chairs\" class=\"w-full flex items-center justify-between px-3 py-2.5 rounded-xl font-medium text-sm transition-all text-slate-600 hover:bg-slate-50\">\n          <div class=\"flex items-center gap-3\">\n            <i class=\"fa-solid fa-chair w-5 text-center text-slate-400\"></i>\n            <span>\u0637\u0644\u0628\u0627\u062A \u062A\u0641\u0635\u064A\u0644 \u0627\u0644\u0643\u0631\u0627\u0633\u064A</span>\n          </div>\n          <span id=\"badge-new-chairs\" class=\"bg-rose-100 text-rose-700 text-[11px] font-bold px-2 py-0.5 rounded-full hidden\">0</span>\n        </button>\n\n        <button onclick=\"switchTab('customers')\" id=\"tab-btn-customers\" class=\"w-full flex items-center justify-between px-3 py-2.5 rounded-xl font-medium text-sm transition-all text-slate-600 hover:bg-slate-50\">\n          <div class=\"flex items-center gap-3\">\n            <i class=\"fa-solid fa-users w-5 text-center text-slate-400\"></i>\n            <span>\u0627\u0644\u0639\u0645\u0644\u0627\u0621 (Clients CRM)</span>\n          </div>\n          <span id=\"badge-clients-count\" class=\"bg-slate-100 text-slate-600 text-[11px] font-bold px-2 py-0.5 rounded-full\">0</span>\n        </button>\n\n        <button onclick=\"switchTab('expenses')\" id=\"tab-btn-expenses\" class=\"w-full flex items-center justify-between px-3 py-2.5 rounded-xl font-medium text-sm transition-all text-slate-600 hover:bg-slate-50\">\n          <div class=\"flex items-center gap-3\">\n            <i class=\"fa-solid fa-receipt w-5 text-center text-slate-400\"></i>\n            <span>\u0627\u0644\u0645\u0635\u0631\u0648\u0641\u0627\u062A \u0648\u0627\u0644\u062A\u0643\u0627\u0644\u064A\u0641</span>\n          </div>\n        </button>\n\n        <button onclick=\"switchTab('shipping')\" id=\"tab-btn-shipping\" class=\"w-full flex items-center justify-between px-3 py-2.5 rounded-xl font-medium text-sm transition-all text-slate-600 hover:bg-slate-50\">\n          <div class=\"flex items-center gap-3\">\n            <i class=\"fa-solid fa-truck-fast w-5 text-center text-slate-400\"></i>\n            <span>\u0627\u0644\u0634\u062D\u0646 \u0648\u0627\u0644\u0645\u062D\u0627\u0641\u0638\u0627\u062A</span>\n          </div>\n          <span class=\"bg-slate-100 text-slate-600 text-[11px] font-bold px-2 py-0.5 rounded-full\">27</span>\n        </button>\n\n        <button onclick=\"switchTab('staff')\" id=\"tab-btn-staff\" class=\"w-full flex items-center justify-between px-3 py-2.5 rounded-xl font-medium text-sm transition-all text-slate-600 hover:bg-slate-50\">\n          <div class=\"flex items-center gap-3\">\n            <i class=\"fa-solid fa-user-shield w-5 text-center text-slate-400\"></i>\n            <span>\u0627\u0644\u0645\u0634\u0631\u0641\u064A\u0646 \u0648\u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0627\u062A</span>\n          </div>\n          <span id=\"badge-staff-count\" class=\"bg-purple-100 text-purple-700 text-[11px] font-bold px-2 py-0.5 rounded-full\">0</span>\n        </button>\n      </nav>\n\n      <!-- Cloud Status Box -->\n      <div class=\"bg-white rounded-2xl border border-slate-200 p-4 mt-4 shadow-sm text-xs text-slate-600 space-y-2\">\n        <div class=\"font-bold text-slate-800 flex items-center gap-2\">\n          <i class=\"fa-solid fa-cloud text-emerald-500\"></i>\n          \u0642\u0627\u0639\u062F\u0629 \u0628\u064A\u0627\u0646\u0627\u062A Supabase \u0627\u0644\u062D\u064A\u0629\n        </div>\n        <div class=\"flex items-center justify-between text-[11px] pt-1 border-t border-slate-100\">\n          <span>\u0627\u0644\u0645\u0634\u0631\u0648\u0639:</span>\n          <span class=\"text-emerald-700 font-mono font-bold\">oyiqebjljvmjuxhsivqq</span>\n        </div>\n        <div class=\"flex items-center justify-between text-[11px]\">\n          <span>\u0642\u0627\u0639\u062F\u0629 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A:</span>\n          <span class=\"text-emerald-600 font-semibold flex items-center gap-1\">\n            <span class=\"w-2 h-2 rounded-full bg-emerald-500 inline-block animate-ping\"></span> \u0645\u062A\u0635\u0644\u0629 \u0648\u062D\u064A\u0629\n          </span>\n        </div>\n      </div>\n    </aside>\n\n    <!-- Main Content Dynamic Panels -->\n    <main class=\"flex-1 min-w-0\">\n\n      <!-- \u2550\u2550\u2550\u2550 1. OVERVIEW & FINANCIALS PANEL \u2550\u2550\u2550\u2550 -->\n      <section id=\"panel-overview\" class=\"space-y-6\">\n        <!-- 6 KPI CARDS (Financials & Metrics) -->\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4\">\n          <!-- Total Revenue -->\n          <div id=\"kpi-card-revenue\" class=\"bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between\">\n            <div>\n              <div class=\"text-xs font-bold text-slate-500\">\u0625\u062C\u0645\u0627\u0644\u064A \u0627\u0644\u0625\u064A\u0631\u0627\u062F\u0627\u062A (Revenue)</div>\n              <div class=\"text-2xl font-black text-slate-900 mt-1\" id=\"kpi-revenue\">0 \u062C.\u0645</div>\n              <div class=\"text-[11px] text-emerald-600 mt-1 flex items-center gap-1 font-semibold\">\n                <i class=\"fa-solid fa-arrow-trend-up\"></i>\n                \u0645\u062C\u0645\u0648\u0639 \u0627\u0644\u0637\u0644\u0628\u0627\u062A \u0627\u0644\u0645\u0633\u062C\u0644\u0629\n              </div>\n            </div>\n            <div class=\"w-12 h-12 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center text-xl\">\n              <i class=\"fa-solid fa-coins\"></i>\n            </div>\n          </div>\n\n          <!-- Total Expenses -->\n          <div id=\"kpi-card-expenses\" class=\"bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between\">\n            <div>\n              <div class=\"text-xs font-bold text-slate-500\">\u0625\u062C\u0645\u0627\u0644\u064A \u0627\u0644\u0645\u0635\u0631\u0648\u0641\u0627\u062A (Expenses)</div>\n              <div class=\"text-2xl font-black text-rose-600 mt-1\" id=\"kpi-expenses\">0 \u062C.\u0645</div>\n              <div class=\"text-[11px] text-rose-600 mt-1 flex items-center gap-1 font-semibold\">\n                <i class=\"fa-solid fa-arrow-trend-down\"></i>\n                \u062A\u0643\u0627\u0644\u064A\u0641 \u0648\u062E\u0627\u0645\u0627\u062A \u0648\u0634\u062D\u0646 \u0648\u062A\u0633\u0648\u064A\u0642\n              </div>\n            </div>\n            <div class=\"w-12 h-12 rounded-xl bg-rose-50 text-rose-600 flex items-center justify-center text-xl\">\n              <i class=\"fa-solid fa-receipt\"></i>\n            </div>\n          </div>\n\n          <!-- Net Profit -->\n          <div id=\"kpi-card-net-profit\" class=\"bg-gradient-to-tr from-emerald-600 to-teal-500 p-5 rounded-2xl text-white shadow-md flex items-center justify-between\">\n            <div>\n              <div class=\"text-xs font-bold text-emerald-100\">\u0635\u0627\u0641\u064A \u0627\u0644\u0623\u0631\u0628\u0627\u062D (Net Profit)</div>\n              <div class=\"text-3xl font-black mt-1\" id=\"kpi-net-profit\">0 \u062C.\u0645</div>\n              <div class=\"text-[11px] text-emerald-100 mt-1 font-semibold\">\n                \u0627\u0644\u0625\u064A\u0631\u0627\u062F\u0627\u062A - \u0627\u0644\u0645\u0635\u0631\u0648\u0641\u0627\u062A\n              </div>\n            </div>\n            <div class=\"w-12 h-12 rounded-xl bg-white/20 text-white flex items-center justify-center text-xl backdrop-blur-sm\">\n              <i class=\"fa-solid fa-chart-line\"></i>\n            </div>\n          </div>\n\n          <!-- Total Orders -->\n          <div class=\"bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between\">\n            <div>\n              <div class=\"text-xs font-bold text-slate-500\">\u0639\u062F\u062F \u0627\u0644\u0637\u0644\u0628\u0627\u062A (Orders)</div>\n              <div class=\"text-2xl font-black text-slate-900 mt-1\" id=\"kpi-orders\">0</div>\n              <div class=\"text-[11px] text-amber-600 mt-1 font-semibold\" id=\"kpi-pending-label\">0 \u0637\u0644\u0628 \u0645\u0639\u0644\u0642</div>\n            </div>\n            <div class=\"w-12 h-12 rounded-xl bg-amber-50 text-amber-600 flex items-center justify-center text-xl\">\n              <i class=\"fa-solid fa-box-archive\"></i>\n            </div>\n          </div>\n\n          <!-- Total Products -->\n          <div class=\"bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between\">\n            <div>\n              <div class=\"text-xs font-bold text-slate-500\">\u0639\u062F\u062F \u0627\u0644\u0645\u0646\u062A\u062C\u0627\u062A (Products)</div>\n              <div class=\"text-2xl font-black text-slate-900 mt-1\" id=\"kpi-products\">0</div>\n              <div class=\"text-[11px] text-slate-400 mt-1\">\u0627\u0644\u0645\u0646\u062A\u062C\u0627\u062A \u0627\u0644\u0646\u0634\u0637\u0629 \u0628\u0627\u0644\u0645\u062A\u062C\u0631</div>\n            </div>\n            <div class=\"w-12 h-12 rounded-xl bg-purple-50 text-purple-600 flex items-center justify-center text-xl\">\n              <i class=\"fa-solid fa-tags\"></i>\n            </div>\n          </div>\n\n          <!-- Total Clients -->\n          <div class=\"bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between\">\n            <div>\n              <div class=\"text-xs font-bold text-slate-500\">\u0639\u062F\u062F \u0627\u0644\u0639\u0645\u0644\u0627\u0621 (Clients)</div>\n              <div class=\"text-2xl font-black text-slate-900 mt-1\" id=\"kpi-clients\">0</div>\n              <div class=\"text-[11px] text-slate-400 mt-1\">\u0627\u0644\u0645\u0633\u062C\u0644\u064A\u0646 \u0641\u064A \u0627\u0644\u0646\u0638\u0627\u0645</div>\n            </div>\n            <div class=\"w-12 h-12 rounded-xl bg-teal-50 text-teal-600 flex items-center justify-center text-xl\">\n              <i class=\"fa-solid fa-users\"></i>\n            </div>\n          </div>\n        </div>\n\n        <!-- Sales Chart & Low Stock Warning -->\n        <div class=\"grid grid-cols-1 lg:grid-cols-3 gap-6\">\n          <div class=\"bg-white p-5 rounded-2xl border border-slate-200 shadow-sm lg:col-span-2 space-y-4\">\n            <div class=\"flex items-center justify-between\">\n              <h2 class=\"font-bold text-slate-900 text-sm flex items-center gap-2\">\n                <i class=\"fa-solid fa-chart-line text-brand-600\"></i>\n                \u0645\u062E\u0637\u0637 \u0627\u0644\u0645\u0628\u064A\u0639\u0627\u062A \u0627\u0644\u064A\u0648\u0645\u064A\u0629\n              </h2>\n              <span class=\"text-xs text-slate-400 font-mono\">\u0628\u064A\u0627\u0646\u0627\u062A \u062D\u064A\u0629 \u0645\u0646 Supabase</span>\n            </div>\n            <div class=\"h-64 relative\">\n              <canvas id=\"salesChartCanvas\"></canvas>\n            </div>\n          </div>\n\n          <!-- Low Stock Alert -->\n          <div class=\"bg-white p-5 rounded-2xl border border-slate-200 shadow-sm space-y-4\">\n            <h2 class=\"font-bold text-slate-900 text-sm flex items-center gap-2 text-rose-600\">\n              <i class=\"fa-solid fa-triangle-exclamation\"></i>\n              \u062A\u0646\u0628\u064A\u0647\u0627\u062A \u0627\u0646\u062E\u0641\u0627\u0636 \u0627\u0644\u0645\u062E\u0632\u0648\u0646\n            </h2>\n            <div id=\"low-stock-list\" class=\"space-y-3\">\n              <!-- populated by JS -->\n            </div>\n          </div>\n        </div>\n\n        <!-- Recent Orders Table -->\n        <div class=\"bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden\">\n          <div class=\"p-5 border-b border-slate-100 flex items-center justify-between\">\n            <h2 class=\"font-bold text-slate-900 text-sm\">\u0623\u062D\u062F\u062B \u0637\u0644\u0628\u0627\u062A \u0627\u0644\u0634\u0631\u0627\u0621 \u0627\u0644\u0645\u0633\u062C\u0644\u0629</h2>\n            <button onclick=\"switchTab('orders')\" class=\"text-xs text-brand-600 hover:text-brand-700 font-semibold\">\n              \u0639\u0631\u0636 \u0643\u0644 \u0627\u0644\u0637\u0644\u0628\u0627\u062A &larr;\n            </button>\n          </div>\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-right text-xs\">\n              <thead class=\"bg-slate-50 text-slate-500 font-bold border-b border-slate-100\">\n                <tr>\n                  <th class=\"p-3\">\u0631\u0642\u0645 \u0627\u0644\u0637\u0644\u0628</th>\n                  <th class=\"p-3\">\u0627\u0644\u0639\u0645\u064A\u0644</th>\n                  <th class=\"p-3\">\u0627\u0644\u0645\u062D\u0627\u0641\u0638\u0629</th>\n                  <th class=\"p-3\">\u0627\u0644\u0625\u062C\u0645\u0627\u0644\u064A</th>\n                  <th class=\"p-3\">\u0627\u0644\u062D\u0627\u0644\u0629</th>\n                  <th class=\"p-3\">\u0627\u0644\u062A\u0627\u0631\u064A\u062E</th>\n                </tr>\n              </thead>\n              <tbody id=\"overview-orders-tbody\" class=\"divide-y divide-slate-100 text-slate-700\">\n                <!-- populated by JS -->\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n\n      <!-- \u2550\u2550\u2550\u2550 2. PRODUCTS PANEL (Full CRUD) \u2550\u2550\u2550\u2550 -->\n      <section id=\"panel-products\" class=\"space-y-4 hidden\">\n        <div class=\"bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col sm:flex-row items-center justify-between gap-4\">\n          <div>\n            <h2 class=\"font-bold text-slate-900 text-base\">\u0643\u062A\u0627\u0644\u0648\u062C \u0627\u0644\u0645\u0646\u062A\u062C\u0627\u062A \u0627\u0644\u0633\u062D\u0627\u0628\u064A</h2>\n            <p class=\"text-xs text-slate-500\">\u0625\u0636\u0627\u0641\u0629 \u0648\u062A\u0639\u062F\u064A\u0644 \u0648\u062D\u0630\u0641 \u0627\u0644\u0645\u0646\u062A\u062C\u0627\u062A\u060C \u0627\u0644\u062A\u062D\u0643\u0645 \u0628\u0627\u0644\u0645\u062E\u0632\u0648\u0646 \u0648\u0631\u0641\u0639 \u0627\u0644\u0635\u0648\u0631 \u0625\u0644\u0649 Supabase Storage</p>\n          </div>\n          <button onclick=\"openProductModal()\" class=\"px-4 py-2.5 bg-brand-600 hover:bg-brand-700 text-white rounded-xl text-xs font-bold shadow-sm transition-colors flex items-center gap-2\">\n            <i class=\"fa-solid fa-plus\"></i>\n            \u0625\u0636\u0627\u0641\u0629 \u0645\u0646\u062A\u062C \u062C\u062F\u064A\u062F\n          </button>\n        </div>\n\n        <div class=\"bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden\">\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-right text-xs\">\n              <thead class=\"bg-slate-50 text-slate-500 font-bold border-b border-slate-100\">\n                <tr>\n                  <th class=\"p-3\">\u0627\u0644\u0645\u0646\u062A\u062C</th>\n                  <th class=\"p-3\">\u0627\u0644\u0642\u0633\u0645</th>\n                  <th class=\"p-3\">\u0627\u0644\u0633\u0639\u0631 \u0627\u0644\u062D\u0627\u0644\u064A</th>\n                  <th class=\"p-3\">\u0627\u0644\u0633\u0639\u0631 \u0627\u0644\u0623\u0635\u0644\u064A</th>\n                  <th class=\"p-3\">\u0627\u0644\u062E\u0635\u0645</th>\n                  <th class=\"p-3\">\u0627\u0644\u0645\u062E\u0632\u0648\u0646</th>\n                  <th class=\"p-3\">\u062D\u0627\u0644\u0629 \u0627\u0644\u062A\u0648\u0641\u0631</th>\n                  <th class=\"p-3 text-center\">\u0625\u062C\u0631\u0627\u0621\u0627\u062A</th>\n                </tr>\n              </thead>\n              <tbody id=\"products-table-tbody\" class=\"divide-y divide-slate-100 text-slate-700\">\n                <!-- populated by JS -->\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n\n      <!-- \u2550\u2550\u2550\u2550 3. CATEGORIES PANEL (Full CRUD) \u2550\u2550\u2550\u2550 -->\n      <section id=\"panel-categories\" class=\"space-y-4 hidden\">\n        <div class=\"bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col sm:flex-row items-center justify-between gap-4\">\n          <div>\n            <h2 class=\"font-bold text-slate-900 text-base\">\u0627\u0644\u0623\u0642\u0633\u0627\u0645 \u0648\u0627\u0644\u062A\u0635\u0646\u064A\u0641\u0627\u062A</h2>\n            <p class=\"text-xs text-slate-500\">\u0627\u0644\u062A\u062D\u0643\u0645 \u0641\u064A \u0623\u0642\u0633\u0627\u0645 \u0627\u0644\u0645\u062A\u062C\u0631\u060C \u0627\u0644\u062A\u0631\u062A\u064A\u0628\u060C \u0627\u0644\u0635\u0648\u0631 \u0648\u0627\u0644\u0638\u0647\u0648\u0631 \u0641\u064A \u0627\u0644\u0645\u0648\u0642\u0639</p>\n          </div>\n          <button onclick=\"openCategoryModal()\" class=\"px-4 py-2.5 bg-brand-600 hover:bg-brand-700 text-white rounded-xl text-xs font-bold shadow-sm transition-colors flex items-center gap-2\">\n            <i class=\"fa-solid fa-plus\"></i>\n            \u0625\u0636\u0627\u0641\u0629 \u0642\u0633\u0645 \u062C\u062F\u064A\u062F\n          </button>\n        </div>\n\n        <div id=\"categories-grid\" class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4\">\n          <!-- populated by JS -->\n        </div>\n      </section>\n\n      <!-- \u2550\u2550\u2550\u2550 4. ORDERS PANEL (Full CRUD) \u2550\u2550\u2550\u2550 -->\n      <section id=\"panel-orders\" class=\"space-y-4 hidden\">\n        <div class=\"bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row items-center justify-between gap-4\">\n          <div class=\"flex items-center gap-2 overflow-x-auto w-full md:w-auto pb-1 md:pb-0\">\n            <button onclick=\"filterOrders('all')\" id=\"btn-order-filter-all\" class=\"px-3 py-1.5 rounded-lg text-xs font-bold bg-brand-600 text-white\">\u0627\u0644\u0643\u0644</button>\n            <button onclick=\"filterOrders('pending')\" id=\"btn-order-filter-pending\" class=\"px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-100 hover:bg-slate-200 text-slate-700\">\u0645\u0639\u0644\u0642</button>\n            <button onclick=\"filterOrders('confirmed')\" id=\"btn-order-filter-confirmed\" class=\"px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-100 hover:bg-slate-200 text-slate-700\">\u0645\u0624\u0643\u062F</button>\n            <button onclick=\"filterOrders('processing')\" id=\"btn-order-filter-processing\" class=\"px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-100 hover:bg-slate-200 text-slate-700\">\u0642\u064A\u062F \u0627\u0644\u062A\u062C\u0647\u064A\u0632</button>\n            <button onclick=\"filterOrders('shipped')\" id=\"btn-order-filter-shipped\" class=\"px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-100 hover:bg-slate-200 text-slate-700\">\u062A\u0645 \u0627\u0644\u0634\u062D\u0646</button>\n            <button onclick=\"filterOrders('delivered')\" id=\"btn-order-filter-delivered\" class=\"px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-100 hover:bg-slate-200 text-slate-700\">\u062A\u0645 \u0627\u0644\u062A\u0633\u0644\u064A\u0645</button>\n            <button onclick=\"filterOrders('cancelled')\" id=\"btn-order-filter-cancelled\" class=\"px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-100 hover:bg-slate-200 text-slate-700\">\u0645\u0644\u063A\u064A</button>\n          </div>\n\n          <div class=\"relative w-full md:w-72\">\n            <input type=\"text\" id=\"orderSearchInput\" oninput=\"handleOrderSearch(this.value)\" placeholder=\"\u0628\u062D\u062B \u0628\u0631\u0642\u0645 \u0627\u0644\u0637\u0644\u0628\u060C \u0627\u0644\u0627\u0633\u0645\u060C \u0623\u0648 \u0627\u0644\u0647\u0627\u062A\u0641...\" class=\"w-full text-xs bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 pr-9 focus:outline-none focus:border-brand-500 font-medium\" />\n            <i class=\"fa-solid fa-search absolute right-3 top-3 text-slate-400 text-xs\"></i>\n          </div>\n        </div>\n\n        <div class=\"bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden\">\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-right text-xs\">\n              <thead class=\"bg-slate-50 text-slate-500 font-bold border-b border-slate-100\">\n                <tr>\n                  <th class=\"p-3\">\u0631\u0642\u0645 \u0627\u0644\u0637\u0644\u0628</th>\n                  <th class=\"p-3\">\u0627\u0644\u0639\u0645\u064A\u0644 \u0648\u0627\u0644\u0647\u0627\u062A\u0641</th>\n                  <th class=\"p-3\">\u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0648\u0627\u0644\u0645\u062D\u0627\u0641\u0638\u0629</th>\n                  <th class=\"p-3\">\u0627\u0644\u0645\u0646\u062A\u062C\u0627\u062A</th>\n                  <th class=\"p-3\">\u0627\u0644\u0625\u062C\u0645\u0627\u0644\u064A</th>\n                  <th class=\"p-3\">\u0637\u0631\u064A\u0642\u0629 \u0627\u0644\u062F\u0641\u0639</th>\n                  <th class=\"p-3\">\u0627\u0644\u062D\u0627\u0644\u0629</th>\n                  <th class=\"p-3 text-center\">\u0625\u062C\u0631\u0627\u0621\u0627\u062A</th>\n                </tr>\n              </thead>\n              <tbody id=\"orders-table-tbody\" class=\"divide-y divide-slate-100 text-slate-700\">\n                <!-- populated by JS -->\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n\n      <!-- \u2550\u2550\u2550\u2550 5. CUSTOM CHAIRS PANEL \u2550\u2550\u2550\u2550 -->\n      <section id=\"panel-custom-chairs\" class=\"space-y-4 hidden\">\n        <div class=\"bg-gradient-to-r from-brand-800 to-brand-600 rounded-2xl p-6 text-white shadow-md flex flex-col md:flex-row items-center justify-between gap-4\">\n          <div>\n            <h2 class=\"text-lg font-black flex items-center gap-2\">\n              <i class=\"fa-solid fa-chair text-amber-300\"></i>\n              \u0634\u0627\u0634\u0629 \u0637\u0644\u0628\u0627\u062A \u062A\u0641\u0635\u064A\u0644 \u0648\u062A\u0644\u0628\u064A\u0633\u0627\u062A \u0627\u0644\u0643\u0631\u0627\u0633\u064A (\u0627\u0644\u0639\u0645\u0648\u0644\u0629)\n            </h2>\n            <p class=\"text-xs text-brand-100 mt-1 max-w-2xl leading-relaxed\">\n              \u0627\u0644\u0643\u0631\u0627\u0633\u064A \u0627\u0644\u0645\u0631\u0641\u0648\u0639\u0629 \u0645\u0646 \u0627\u0644\u0639\u0645\u0644\u0627\u0621 \u0645\u0639 \u0635\u0648\u0631 \u0643\u0631\u0627\u0633\u064A\u0647\u0645 \u0627\u0644\u062E\u0627\u0635\u0629 \u0644\u062A\u0641\u0635\u064A\u0644 \u062A\u0644\u0628\u064A\u0633\u0629 \u0628\u0627\u0644\u0645\u0644\u0644\u064A (+200 \u062C\u0646\u064A\u0647). \u062A\u0648\u0627\u0635\u0644 \u0645\u0639 \u0627\u0644\u0639\u0645\u064A\u0644 \u0628\u0646\u0642\u0631\u0629 \u0648\u0627\u062D\u062F\u0629 \u0639\u0628\u0631 \u0627\u0644\u0648\u0627\u062A\u0633\u0627\u0628 \u0644\u062A\u0623\u0643\u064A\u062F \u0627\u0644\u0645\u0642\u0627\u0633\u0627\u062A.\n            </p>\n          </div>\n          <button onclick=\"loadChairRequests()\" class=\"px-4 py-2 bg-white/10 hover:bg-white/20 backdrop-blur rounded-xl text-xs font-bold transition-colors\">\n            <i class=\"fa-solid fa-rotate-right ml-1\"></i>\n            \u062A\u062D\u062F\u064A\u062B \u0627\u0644\u0637\u0644\u0628\u0627\u062A\n          </button>\n        </div>\n\n        <!-- Custom Chair Cards Grid -->\n        <div id=\"chair-requests-grid\" class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5\">\n          <!-- populated by JS -->\n        </div>\n      </section>\n\n      <!-- \u2550\u2550\u2550\u2550 6. CLIENTS / CUSTOMERS CRM PANEL (Full CRUD) \u2550\u2550\u2550\u2550 -->\n      <section id=\"panel-customers\" class=\"space-y-4 hidden\">\n        <div class=\"bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col sm:flex-row items-center justify-between gap-4\">\n          <div>\n            <h2 class=\"font-bold text-slate-900 text-base\">\u0633\u062C\u0644 \u0627\u0644\u0639\u0645\u0644\u0627\u0621 \u0648\u0625\u062F\u0627\u0631\u0629 \u0627\u0644\u0639\u0644\u0627\u0642\u0627\u062A (Clients CRM)</h2>\n            <p class=\"text-xs text-slate-500\">\u0625\u0636\u0627\u0641\u0629 \u0639\u0645\u0644\u0627\u0621 \u064A\u062F\u0648\u064A\u064A\u0646\u060C \u0627\u0633\u062A\u0639\u0631\u0627\u0636 \u0633\u062C\u0644 \u0637\u0644\u0628\u0627\u062A\u0647\u0645\u060C \u0648\u062A\u0648\u0627\u0635\u0644 \u0648\u0627\u062A\u0633\u0627\u0628 \u0645\u0628\u0627\u0634\u0631</p>\n          </div>\n          <button onclick=\"openCustomerModal()\" class=\"px-4 py-2.5 bg-brand-600 hover:bg-brand-700 text-white rounded-xl text-xs font-bold shadow-sm transition-colors flex items-center gap-2\">\n            <i class=\"fa-solid fa-user-plus\"></i>\n            \u0625\u0636\u0627\u0641\u0629 \u0639\u0645\u064A\u0644 \u062C\u062F\u064A\u062F\n          </button>\n        </div>\n\n        <div class=\"bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden\">\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-right text-xs\">\n              <thead class=\"bg-slate-50 text-slate-500 font-bold border-b border-slate-100\">\n                <tr>\n                  <th class=\"p-3\">\u0627\u0644\u0639\u0645\u064A\u0644</th>\n                  <th class=\"p-3\">\u0631\u0642\u0645 \u0627\u0644\u0647\u0627\u062A\u0641</th>\n                  <th class=\"p-3\">\u0627\u0644\u0645\u062D\u0627\u0641\u0638\u0629 / \u0627\u0644\u0645\u062F\u064A\u0646\u0629</th>\n                  <th class=\"p-3\">\u0639\u062F\u062F \u0627\u0644\u0637\u0644\u0628\u0627\u062A</th>\n                  <th class=\"p-3\">\u0625\u062C\u0645\u0627\u0644\u064A \u0627\u0644\u0625\u0646\u0641\u0627\u0642</th>\n                  <th class=\"p-3 text-center\">\u0625\u062C\u0631\u0627\u0621\u0627\u062A</th>\n                </tr>\n              </thead>\n              <tbody id=\"customers-table-tbody\" class=\"divide-y divide-slate-100 text-slate-700\">\n                <!-- populated by JS -->\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n\n      <!-- \u2550\u2550\u2550\u2550 7. EXPENSES PANEL (Accounting & Financials) \u2550\u2550\u2550\u2550 -->\n      <section id=\"panel-expenses\" class=\"space-y-4 hidden\">\n        <div class=\"bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col sm:flex-row items-center justify-between gap-4\">\n          <div>\n            <h2 class=\"font-bold text-slate-900 text-base\">\u0625\u062F\u0627\u0631\u0629 \u0627\u0644\u0645\u0635\u0631\u0648\u0641\u0627\u062A \u0648\u0627\u0644\u062A\u0643\u0627\u0644\u064A\u0641 (Expenses)</h2>\n            <p class=\"text-xs text-slate-500\">\u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u062E\u0627\u0645\u0627\u062A\u060C \u062A\u0643\u0627\u0644\u064A\u0641 \u0627\u0644\u0634\u062D\u0646\u060C \u0627\u0644\u062D\u0645\u0644\u0627\u062A \u0627\u0644\u0625\u0639\u0644\u0627\u0646\u064A\u0629\u060C \u0648\u0627\u0644\u0625\u064A\u062C\u0627\u0631\u0627\u062A \u0644\u062D\u0633\u0627\u0628 \u0635\u0627\u0641\u064A \u0627\u0644\u0631\u0628\u062D \u0628\u062F\u0642\u0629</p>\n          </div>\n          <button onclick=\"openExpenseModal()\" class=\"px-4 py-2.5 bg-rose-600 hover:bg-rose-700 text-white rounded-xl text-xs font-bold shadow-sm transition-colors flex items-center gap-2\">\n            <i class=\"fa-solid fa-plus\"></i>\n            \u0625\u0636\u0627\u0641\u0629 \u0628\u0646\u062F \u0645\u0635\u0631\u0648\u0641 \u062C\u062F\u064A\u062F\n          </button>\n        </div>\n\n        <div class=\"bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden\">\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-right text-xs\">\n              <thead class=\"bg-slate-50 text-slate-500 font-bold border-b border-slate-100\">\n                <tr>\n                  <th class=\"p-3\">\u0628\u0646\u062F \u0627\u0644\u0645\u0635\u0631\u0648\u0641</th>\n                  <th class=\"p-3\">\u0627\u0644\u062A\u0635\u0646\u064A\u0641</th>\n                  <th class=\"p-3\">\u0627\u0644\u0645\u0628\u0644\u063A (\u062C.\u0645)</th>\n                  <th class=\"p-3\">\u0627\u0644\u062A\u0627\u0631\u064A\u062E</th>\n                  <th class=\"p-3\">\u0645\u0644\u0627\u062D\u0638\u0627\u062A</th>\n                  <th class=\"p-3 text-center\">\u0625\u062C\u0631\u0627\u0621</th>\n                </tr>\n              </thead>\n              <tbody id=\"expenses-table-tbody\" class=\"divide-y divide-slate-100 text-slate-700\">\n                <!-- populated by JS -->\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n\n      <!-- \u2550\u2550\u2550\u2550 8. SHIPPING PANEL (Translated with explicit Arabic Badges) \u2550\u2550\u2550\u2550 -->\n      <section id=\"panel-shipping\" class=\"space-y-4 hidden\">\n        <div class=\"bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col sm:flex-row items-center justify-between gap-4\">\n          <div>\n            <h2 class=\"font-bold text-slate-900 text-base\">\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u0634\u062D\u0646 \u0648\u0645\u062D\u0627\u0641\u0638\u0627\u062A \u0645\u0635\u0631 (27 \u0645\u062D\u0627\u0641\u0638\u0629)</h2>\n            <p class=\"text-xs text-slate-500\">\u062A\u0639\u062F\u064A\u0644 \u062A\u0643\u0627\u0644\u064A\u0641 \u0627\u0644\u0634\u062D\u0646 \u0648\u0627\u0644\u0645\u062F\u0629 \u0627\u0644\u062A\u0642\u062F\u064A\u0631\u064A\u0629 \u0648\u062A\u0641\u0639\u064A\u0644/\u062A\u0639\u0637\u064A\u0644 \u0627\u0644\u062A\u0648\u0635\u064A\u0644 \u0644\u0623\u064A \u0645\u062D\u0627\u0641\u0638\u0629</p>\n          </div>\n          <div class=\"text-xs text-emerald-600 font-semibold flex items-center gap-1.5 bg-emerald-50 px-3 py-1.5 rounded-xl border border-emerald-100\">\n            <i class=\"fa-solid fa-check-circle\"></i>\n            \u0645\u062A\u0635\u0644\u0629 \u0633\u062D\u0627\u0628\u064A\u0627\u064B \u0645\u0639 Supabase\n          </div>\n        </div>\n\n        <div class=\"bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden\">\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-right text-xs\">\n              <thead class=\"bg-slate-50 text-slate-500 font-bold border-b border-slate-100\">\n                <tr>\n                  <th class=\"p-3\">\u0627\u0644\u0645\u062D\u0627\u0641\u0638\u0629</th>\n                  <th class=\"p-3\">\u062A\u0643\u0644\u0641\u0629 \u0627\u0644\u0634\u062D\u0646 (\u062C.\u0645)</th>\n                  <th class=\"p-3\">\u0645\u062F\u0629 \u0627\u0644\u062A\u0648\u0635\u064A\u0644 \u0627\u0644\u062A\u0642\u062F\u064A\u0631\u064A\u0629</th>\n                  <th class=\"p-3\">\u062D\u0627\u0644\u0629 \u0627\u0644\u062A\u0648\u0635\u064A\u0644 \u0644\u0644\u0634\u062D\u0646</th>\n                  <th class=\"p-3 text-center\">\u062D\u0641\u0638 \u0627\u0644\u062A\u0639\u062F\u064A\u0644</th>\n                </tr>\n              </thead>\n              <tbody id=\"shipping-table-tbody\" class=\"divide-y divide-slate-100 text-slate-700\">\n                <!-- populated by JS -->\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n\n      <!-- \u2550\u2550\u2550\u2550 9. STAFF & ROLES PANEL (RBAC & Permissions) \u2550\u2550\u2550\u2550 -->\n      <section id=\"panel-staff\" class=\"space-y-6 hidden\">\n        <div class=\"bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex flex-col sm:flex-row items-center justify-between gap-4\">\n          <div>\n            <h2 class=\"font-bold text-slate-900 text-lg flex items-center gap-2\">\n              <i class=\"fa-solid fa-user-shield text-brand-600\"></i>\n              <span>\u0625\u062F\u0627\u0631\u0629 \u0627\u0644\u0645\u0634\u0631\u0641\u064A\u0646 \u0648\u0627\u0644\u0623\u062F\u0648\u0627\u0631 \u0648\u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0627\u062A (Permissions Module)</span>\n            </h2>\n            <p class=\"text-xs text-slate-500 mt-1\">\u0627\u0644\u062A\u062D\u0643\u0645 \u0627\u0644\u062F\u0642\u064A\u0642 \u0641\u064A \u0635\u0644\u0627\u062D\u064A\u0627\u062A \u0627\u0644\u0648\u0635\u0648\u0644 \u0648\u0625\u062E\u0641\u0627\u0621 \u0627\u0644\u0623\u0642\u0633\u0627\u0645 \u063A\u064A\u0631 \u0627\u0644\u0645\u0635\u0631\u062D \u0628\u0647\u0627 \u0641\u0648\u0631\u064A\u0627\u064B \u0644\u0643\u0644 \u0645\u0634\u0631\u0641</p>\n          </div>\n          <button onclick=\"openStaffModal()\" class=\"px-5 py-2.5 bg-brand-600 hover:bg-brand-700 text-white rounded-xl text-xs font-bold shadow-md shadow-brand-600/20 transition-all flex items-center gap-2\">\n            <i class=\"fa-solid fa-plus\"></i>\n            \u0625\u0636\u0627\u0641\u0629 \u0645\u0634\u0631\u0641 \u0648\u0635\u0644\u0627\u062D\u064A\u0627\u062A\n          </button>\n        </div>\n\n        <!-- 4 Role Stats Cards -->\n        <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-4\">\n          <div class=\"bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex items-center justify-between\">\n            <div>\n              <div class=\"text-[11px] font-bold text-slate-400\">\u0625\u062C\u0645\u0627\u0644\u064A \u0627\u0644\u0645\u0634\u0631\u0641\u064A\u0646</div>\n              <div class=\"text-xl font-black text-slate-900 mt-1\" id=\"stat-staff-total\">0</div>\n            </div>\n            <div class=\"w-10 h-10 rounded-xl bg-purple-50 text-purple-600 flex items-center justify-center text-lg\">\n              <i class=\"fa-solid fa-users-gear\"></i>\n            </div>\n          </div>\n          <div class=\"bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex items-center justify-between\">\n            <div>\n              <div class=\"text-[11px] font-bold text-purple-600\">\u0645\u062F\u064A\u0631 \u0639\u0627\u0645 (ADMIN)</div>\n              <div class=\"text-xl font-black text-purple-700 mt-1\" id=\"stat-staff-admins\">0</div>\n            </div>\n            <div class=\"w-10 h-10 rounded-xl bg-purple-100 text-purple-700 flex items-center justify-center text-lg\">\n              <i class=\"fa-solid fa-crown\"></i>\n            </div>\n          </div>\n          <div class=\"bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex items-center justify-between\">\n            <div>\n              <div class=\"text-[11px] font-bold text-blue-600\">\u0645\u0634\u0631\u0641 \u0639\u0645\u0644\u064A\u0627\u062A (MANAGER)</div>\n              <div class=\"text-xl font-black text-blue-700 mt-1\" id=\"stat-staff-managers\">0</div>\n            </div>\n            <div class=\"w-10 h-10 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center text-lg\">\n              <i class=\"fa-solid fa-briefcase\"></i>\n            </div>\n          </div>\n          <div class=\"bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex items-center justify-between\">\n            <div>\n              <div class=\"text-[11px] font-bold text-teal-600\">\u062E\u062F\u0645\u0629 \u0639\u0645\u0644\u0627\u0621 (SUPPORT)</div>\n              <div class=\"text-xl font-black text-teal-700 mt-1\" id=\"stat-staff-support\">0</div>\n            </div>\n            <div class=\"w-10 h-10 rounded-xl bg-teal-50 text-teal-600 flex items-center justify-center text-lg\">\n              <i class=\"fa-solid fa-headset\"></i>\n            </div>\n          </div>\n        </div>\n\n        <!-- Role & Permissions Matrix Guide -->\n        <div class=\"bg-gradient-to-r from-slate-900 to-slate-800 text-white rounded-2xl p-5 shadow-sm space-y-3\">\n          <div class=\"flex items-center justify-between\">\n            <div class=\"flex items-center gap-2 font-bold text-sm\">\n              <i class=\"fa-solid fa-shield-halved text-brand-400\"></i>\n              <span>\u0645\u0635\u0641\u0648\u0641\u0629 \u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0627\u062A \u0627\u0644\u0645\u0639\u062A\u0645\u062F\u0629 \u0641\u064A \u0627\u0644\u0646\u0638\u0627\u0645 (Role-Based Permissions Matrix)</span>\n            </div>\n            <span class=\"text-[11px] bg-white/10 px-2.5 py-1 rounded-full font-medium text-slate-300\">\u0646\u0638\u0627\u0645 \u062D\u062C\u0628 \u0627\u0644\u0623\u0642\u0633\u0627\u0645 \u062A\u0644\u0642\u0627\u0626\u064A\u0627\u064B</span>\n          </div>\n          <div class=\"grid grid-cols-1 md:grid-cols-3 gap-3 text-xs pt-1\">\n            <div class=\"bg-white/5 border border-white/10 rounded-xl p-3 space-y-1.5\">\n              <div class=\"font-bold text-purple-300 flex items-center gap-1.5\">\n                <i class=\"fa-solid fa-crown text-xs\"></i>\n                \u0645\u062F\u064A\u0631 \u0639\u0627\u0645 (ADMIN)\n              </div>\n              <p class=\"text-[11px] text-slate-300\">\u0648\u0635\u0648\u0644 \u0643\u0627\u0645\u0644 \u0644\u062C\u0645\u064A\u0639 \u0627\u0644\u0623\u0642\u0633\u0627\u0645 \u0627\u0644\u0640 9: \u0646\u0638\u0631\u0629 \u0639\u0627\u0645\u0629\u060C \u0627\u0644\u0623\u0631\u0628\u0627\u062D \u0648\u0627\u0644\u0645\u0635\u0631\u0648\u0641\u0627\u062A \u0627\u0644\u0645\u0627\u0644\u064A\u0629\u060C \u0627\u0644\u0645\u0646\u062A\u062C\u0627\u062A\u060C \u0627\u0644\u0637\u0644\u0628\u0627\u062A\u060C \u0627\u0644\u0643\u0631\u0627\u0633\u064A\u060C \u0627\u0644\u0639\u0645\u0644\u0627\u0621\u060C \u0627\u0644\u0634\u062D\u0646\u060C \u0648\u0625\u062F\u0627\u0631\u0629 \u0627\u0644\u0645\u0634\u0631\u0641\u064A\u0646.</p>\n            </div>\n            <div class=\"bg-white/5 border border-white/10 rounded-xl p-3 space-y-1.5\">\n              <div class=\"font-bold text-blue-300 flex items-center gap-1.5\">\n                <i class=\"fa-solid fa-briefcase text-xs\"></i>\n                \u0645\u0634\u0631\u0641 \u0639\u0645\u0644\u064A\u0627\u062A (MANAGER)\n              </div>\n              <p class=\"text-[11px] text-slate-300\">\u0648\u0635\u0648\u0644 \u062A\u0634\u063A\u064A\u0644\u064A \u0625\u0644\u0649: \u0627\u0644\u0645\u0646\u062A\u062C\u0627\u062A\u060C \u0627\u0644\u0623\u0642\u0633\u0627\u0645\u060C \u0627\u0644\u0637\u0644\u0628\u0627\u062A\u060C \u0627\u0644\u0643\u0631\u0627\u0633\u064A \u0627\u0644\u0639\u0645\u0648\u0644\u0629\u060C \u0627\u0644\u0639\u0645\u0644\u0627\u0621 CRM\u060C \u0648\u0627\u0644\u0634\u062D\u0646. (\u062A\u064F\u062D\u062C\u0628 \u0627\u0644\u0645\u0627\u0644\u064A\u0629 \u0648\u0635\u0627\u0641\u064A \u0627\u0644\u0623\u0631\u0628\u0627\u062D \u0648\u0625\u062F\u0627\u0631\u0629 \u0627\u0644\u0645\u0634\u0631\u0641\u064A\u0646 \u062A\u0644\u0642\u0627\u0626\u064A\u0627\u064B).</p>\n            </div>\n            <div class=\"bg-white/5 border border-white/10 rounded-xl p-3 space-y-1.5\">\n              <div class=\"font-bold text-teal-300 flex items-center gap-1.5\">\n                <i class=\"fa-solid fa-headset text-xs\"></i>\n                \u062E\u062F\u0645\u0629 \u0639\u0645\u0644\u0627\u0621 (SUPPORT)\n              </div>\n              <p class=\"text-[11px] text-slate-300\">\u0648\u0635\u0648\u0644 \u0645\u062D\u062F\u0648\u062F \u0641\u0642\u0637 \u0625\u0644\u0649: \u0645\u062A\u0627\u0628\u0639\u0629 \u0627\u0644\u0637\u0644\u0628\u0627\u062A\u060C \u0648\u062A\u0641\u0635\u064A\u0644 \u0643\u0631\u0627\u0633\u064A \u0627\u0644\u0633\u0641\u0631\u0629 \u0627\u0644\u0639\u0645\u0648\u0644\u0629 \u0648\u0627\u0644\u0648\u0627\u062A\u0633\u0627\u0628. (\u062A\u064F\u062D\u062C\u0628 \u062C\u0645\u064A\u0639 \u0627\u0644\u0623\u0642\u0633\u0627\u0645 \u0648\u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u062D\u0633\u0627\u0633\u0629 \u0627\u0644\u0623\u062E\u0631\u0649 \u062A\u0645\u0627\u0645\u0627\u064B).</p>\n            </div>\n          </div>\n        </div>\n\n        <!-- Staff Table -->\n        <div class=\"bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden\">\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-right text-xs\">\n              <thead class=\"bg-slate-50 text-slate-500 font-bold border-b border-slate-100\">\n                <tr>\n                  <th class=\"p-3\">\u0627\u0644\u0645\u0634\u0631\u0641</th>\n                  <th class=\"p-3\">\u0627\u0644\u0628\u0631\u064A\u062F \u0627\u0644\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A</th>\n                  <th class=\"p-3\">\u0627\u0644\u0631\u062A\u0628\u0629</th>\n                  <th class=\"p-3\">\u0627\u0644\u0623\u0642\u0633\u0627\u0645 \u0627\u0644\u0645\u0635\u0631\u062D \u0628\u0647\u0627</th>\n                  <th class=\"p-3\">\u0627\u0644\u062D\u0627\u0644\u0629</th>\n                  <th class=\"p-3\">\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0625\u0646\u0634\u0627\u0621</th>\n                  <th class=\"p-3 text-center\">\u0627\u0644\u0625\u062C\u0631\u0627\u0621\u0627\u062A</th>\n                </tr>\n              </thead>\n              <tbody id=\"staff-table-tbody\" class=\"divide-y divide-slate-100 text-slate-700\">\n                <!-- populated by JS -->\n              </tbody>\n            </table>\n          </div>\n        </div>\n\n        <!-- \u2550\u2550\u2550\u2550 Permissions Registry Management Module \u2550\u2550\u2550\u2550 -->\n        <div class=\"bg-white rounded-2xl border border-slate-200 shadow-sm p-5 space-y-4\">\n          <div class=\"flex flex-col sm:flex-row items-center justify-between gap-3 border-b border-slate-100 pb-3\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 text-sm flex items-center gap-2\">\n                <i class=\"fa-solid fa-key text-brand-600\"></i>\n                <span>\u0633\u062C\u0644 \u0635\u0644\u0627\u062D\u064A\u0627\u062A \u0627\u0644\u0646\u0638\u0627\u0645 \u0627\u0644\u0645\u062A\u0627\u062D\u0629 (Permissions Registry Module)</span>\n              </h3>\n              <p class=\"text-[11px] text-slate-500 mt-0.5\">\u0625\u0636\u0627\u0641\u0629 \u0623\u0648 \u062D\u0630\u0641 \u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0627\u062A \u0648\u0631\u0628\u0637\u0647\u0627 \u0627\u0644\u0641\u0648\u0631\u064A \u0628\u0645\u0635\u0641\u0648\u0641\u0629 \u0635\u0644\u0627\u062D\u064A\u0627\u062A \u0627\u0644\u0645\u0634\u0631\u0641\u064A\u0646</p>\n            </div>\n            <button onclick=\"openPermissionModal()\" class=\"px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl text-xs font-bold shadow-sm flex items-center gap-2 transition-all\">\n              <i class=\"fa-solid fa-plus\"></i>\n              \u0625\u0636\u0627\u0641\u0629 \u0635\u0644\u0627\u062D\u064A\u0629 \u062C\u062F\u064A\u062F\u0629 \u0644\u0644\u0646\u0638\u0627\u0645\n            </button>\n          </div>\n\n          <div class=\"grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3\" id=\"permissions-registry-grid\">\n            <!-- populated by JS -->\n          </div>\n        </div>\n      </section>\n\n    </main>\n  </div>\n\n  <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 MODALS (All in-place without native alerts) \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n\n  <!-- 1. DELETE CONFIRMATION DIALOG MODAL -->\n  <div id=\"deleteConfirmModal\" class=\"fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[90] flex items-center justify-center p-4 hidden\">\n    <div class=\"bg-white rounded-2xl max-w-sm w-full p-6 shadow-2xl text-center space-y-4\">\n      <div class=\"w-14 h-14 rounded-2xl bg-rose-100 text-rose-600 flex items-center justify-center text-2xl mx-auto\">\n        <i class=\"fa-solid fa-triangle-exclamation\"></i>\n      </div>\n      <div>\n        <h3 class=\"font-black text-base text-slate-900\" id=\"delModalTitle\">\u062A\u0623\u0643\u064A\u062F \u0639\u0645\u0644\u064A\u0629 \u0627\u0644\u062D\u0630\u0641</h3>\n        <p class=\"text-xs text-slate-500 mt-1\" id=\"delModalDesc\">\u0647\u0644 \u0623\u0646\u062A \u0645\u062A\u0623\u0643\u062F \u0645\u0646 \u0631\u063A\u0628\u062A\u0643 \u0641\u064A \u062D\u0630\u0641 \u0647\u0630\u0627 \u0627\u0644\u0639\u0646\u0635\u0631 \u0646\u0647\u0627\u0626\u064A\u0627\u064B \u0645\u0646 \u0642\u0627\u0639\u062F\u0629 \u0628\u064A\u0627\u0646\u0627\u062A Supabase\u061F \u0644\u0627 \u064A\u0645\u0643\u0646 \u0627\u0644\u062A\u0631\u0627\u062C\u0639 \u0639\u0646 \u0647\u0630\u0627 \u0627\u0644\u0625\u062C\u0631\u0627\u0621.</p>\n      </div>\n      <div class=\"flex items-center justify-center gap-3 pt-2\">\n        <button onclick=\"closeDeleteModal()\" class=\"px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold text-xs\">\u0625\u0644\u063A\u0627\u0621</button>\n        <button id=\"delModalConfirmBtn\" class=\"px-5 py-2 bg-rose-600 hover:bg-rose-700 text-white rounded-xl font-bold text-xs shadow-md shadow-rose-600/20\">\u062A\u0623\u0643\u064A\u062F \u0627\u0644\u062D\u0630\u0641</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- 2. PRODUCT (Add / Edit) MODAL -->\n  <div id=\"productModal\" class=\"fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 hidden\">\n    <div class=\"bg-white rounded-2xl max-w-2xl w-full p-6 max-h-[90vh] overflow-y-auto custom-scrollbar shadow-xl text-right\">\n      <div class=\"flex items-center justify-between border-b border-slate-100 pb-3\">\n        <h3 class=\"font-bold text-base text-slate-900\" id=\"productModalTitle\">\u0625\u0636\u0627\u0641\u0629 \u0645\u0646\u062A\u062C \u062C\u062F\u064A\u062F</h3>\n        <button onclick=\"closeProductModal()\" class=\"text-slate-400 hover:text-slate-600 p-2 text-base\"><i class=\"fa-solid fa-xmark\"></i></button>\n      </div>\n\n      <form id=\"productForm\" onsubmit=\"handleProductSubmit(event)\" class=\"mt-4 space-y-4 text-xs\">\n        <input type=\"hidden\" id=\"prodEditId\" value=\"\" />\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0633\u0645 \u0627\u0644\u0645\u0646\u062A\u062C \u0628\u0627\u0644\u0639\u0631\u0628\u064A\u0629 *</label>\n            <input type=\"text\" id=\"prodName\" required placeholder=\"\u0645\u062B\u0627\u0644: \u0637\u0642\u0645 \u062A\u0644\u0628\u064A\u0633\u0627\u062A \u0643\u0631\u0627\u0633\u064A \u0633\u0641\u0631\u0629 6 \u0642\u0637\u0639\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n          </div>\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0644\u0645\u0639\u0631\u0641 \u0627\u0644\u0641\u0631\u064A\u062F (Slug) *</label>\n            <input type=\"text\" id=\"prodSlug\" required placeholder=\"chair-cover-elastic\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none font-mono\" />\n          </div>\n        </div>\n\n        <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-4\">\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0644\u0642\u0633\u0645 *</label>\n            <select id=\"prodCategory\" required class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none font-semibold\"></select>\n          </div>\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0644\u0633\u0639\u0631 \u0627\u0644\u062D\u0627\u0644\u064A (\u062C.\u0645) *</label>\n            <input type=\"number\" id=\"prodPrice\" required min=\"1\" step=\"0.5\" placeholder=\"150\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n          </div>\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0644\u0633\u0639\u0631 \u0627\u0644\u0623\u0635\u0644\u064A (\u0642\u0628\u0644 \u0627\u0644\u062E\u0635\u0645)</label>\n            <input type=\"number\" id=\"prodOriginalPrice\" min=\"1\" step=\"0.5\" placeholder=\"220\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n          </div>\n        </div>\n\n        <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-4\">\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">\u0646\u0633\u0628\u0629 \u0627\u0644\u062E\u0635\u0645 %</label>\n            <input type=\"number\" id=\"prodDiscount\" min=\"0\" max=\"100\" placeholder=\"32\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n          </div>\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0644\u0643\u0645\u064A\u0629 \u0628\u0627\u0644\u0645\u062E\u0632\u0648\u0646</label>\n            <input type=\"number\" id=\"prodStock\" min=\"0\" value=\"20\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n          </div>\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0644\u062E\u0627\u0645\u0629</label>\n            <input type=\"text\" id=\"prodMaterial\" placeholder=\"\u0644\u064A\u0643\u0631\u0627 \u062C\u0627\u0643\u0627\u0631 \u0645\u0637\u0627\u0637\u064A\u0629\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n          </div>\n        </div>\n\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">\u0648\u0635\u0641 \u0627\u0644\u0645\u0646\u062A\u062C</label>\n          <textarea id=\"prodDescription\" rows=\"3\" placeholder=\"\u0627\u0643\u062A\u0628 \u0645\u0648\u0627\u0635\u0641\u0627\u062A \u0627\u0644\u0645\u0646\u062A\u062C...\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\"></textarea>\n        </div>\n\n        <!-- Supabase Storage Image Upload -->\n        <div class=\"bg-slate-50 p-4 rounded-xl border border-slate-200 space-y-2\">\n          <label class=\"block font-bold text-slate-700\">\u0635\u0648\u0631\u0629 \u0627\u0644\u0645\u0646\u062A\u062C (\u0631\u0641\u0639 \u0645\u0628\u0627\u0634\u0631 \u0625\u0644\u0649 Supabase Storage)</label>\n          <div class=\"flex items-center gap-3\">\n            <input type=\"file\" id=\"prodImageFile\" accept=\"image/*\" class=\"text-xs file:ml-3 file:py-1.5 file:px-3 file:rounded-lg file:border-0 file:text-xs file:font-bold file:bg-brand-50 file:text-brand-700 hover:file:bg-brand-100 cursor-pointer\" />\n            <button type=\"button\" onclick=\"uploadProductImage()\" class=\"px-3 py-1.5 bg-brand-700 text-white rounded-lg font-bold text-xs hover:bg-brand-800 transition-colors\">\n              <i class=\"fa-solid fa-cloud-arrow-up ml-1\"></i> \u0631\u0641\u0639 \u0627\u0644\u0635\u0648\u0631\u0629\n            </button>\n          </div>\n          <input type=\"text\" id=\"prodImageUrl\" placeholder=\"\u0623\u0648 \u0623\u062F\u062E\u0644 \u0631\u0627\u0628\u0637 \u0627\u0644\u0635\u0648\u0631\u0629...\" class=\"w-full bg-white border border-slate-200 rounded-lg p-2 focus:border-brand-500 focus:outline-none text-[11px]\" />\n          <div id=\"prodImagePreviewContainer\" class=\"hidden mt-2\">\n            <img id=\"prodImagePreview\" src=\"\" class=\"w-20 h-20 rounded-xl object-cover border border-slate-200\" />\n          </div>\n        </div>\n\n        <div class=\"flex flex-wrap gap-4 pt-1\">\n          <label class=\"flex items-center gap-2 cursor-pointer\">\n            <input type=\"checkbox\" id=\"prodInStock\" checked class=\"rounded text-brand-600 w-4 h-4\" />\n            <span class=\"font-bold text-slate-700\">\u0645\u062A\u0648\u0641\u0631 \u0641\u064A \u0627\u0644\u0645\u062E\u0632\u0648\u0646</span>\n          </label>\n          <label class=\"flex items-center gap-2 cursor-pointer\">\n            <input type=\"checkbox\" id=\"prodIsFeatured\" class=\"rounded text-brand-600 w-4 h-4\" />\n            <span class=\"font-bold text-slate-700\">\u0645\u0646\u062A\u062C \u0645\u0645\u064A\u0632 (Featured)</span>\n          </label>\n          <label class=\"flex items-center gap-2 cursor-pointer\">\n            <input type=\"checkbox\" id=\"prodIsOnSale\" class=\"rounded text-brand-600 w-4 h-4\" />\n            <span class=\"font-bold text-slate-700\">\u0639\u0631\u0636 \u0648\u062E\u0635\u0645 (Sale)</span>\n          </label>\n          <label class=\"flex items-center gap-2 cursor-pointer\">\n            <input type=\"checkbox\" id=\"prodIsChairCover\" class=\"rounded text-brand-600 w-4 h-4\" />\n            <span class=\"font-bold text-slate-700\">\u062A\u0644\u0628\u064A\u0633\u0629 \u0643\u0631\u0627\u0633\u064A (\u062A\u0641\u0639\u064A\u0644 \u062E\u064A\u0627\u0631 \u0627\u0644\u0639\u0645\u0648\u0644\u0629)</span>\n          </label>\n        </div>\n\n        <div class=\"mt-6 flex items-center justify-end gap-3 pt-4 border-t border-slate-100\">\n          <button type=\"button\" onclick=\"closeProductModal()\" class=\"px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold\">\u0625\u0644\u063A\u0627\u0621</button>\n          <button type=\"submit\" id=\"prodSubmitBtn\" class=\"px-5 py-2 bg-brand-600 hover:bg-brand-700 text-white rounded-xl font-bold shadow-sm\">\u062D\u0641\u0638 \u0627\u0644\u0645\u0646\u062A\u062C</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- 3. CATEGORY (Add / Edit) MODAL -->\n  <div id=\"categoryModal\" class=\"fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 hidden\">\n    <div class=\"bg-white rounded-2xl max-w-lg w-full p-6 shadow-xl text-right\">\n      <div class=\"flex items-center justify-between border-b border-slate-100 pb-3\">\n        <h3 class=\"font-bold text-base text-slate-900\" id=\"categoryModalTitle\">\u0625\u0636\u0627\u0641\u0629 \u0642\u0633\u0645 \u062C\u062F\u064A\u062F</h3>\n        <button onclick=\"closeCategoryModal()\" class=\"text-slate-400 hover:text-slate-600 p-2 text-base\"><i class=\"fa-solid fa-xmark\"></i></button>\n      </div>\n\n      <form id=\"categoryForm\" onsubmit=\"handleCategorySubmit(event)\" class=\"mt-4 space-y-4 text-xs\">\n        <input type=\"hidden\" id=\"catEditId\" value=\"\" />\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0633\u0645 \u0627\u0644\u0642\u0633\u0645 \u0628\u0627\u0644\u0639\u0631\u0628\u064A\u0629 *</label>\n          <input type=\"text\" id=\"catName\" required placeholder=\"\u0645\u0641\u0631\u0648\u0634\u0627\u062A \u063A\u0631\u0641 \u0627\u0644\u0645\u0639\u064A\u0634\u0629\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n        </div>\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0644\u0645\u0639\u0631\u0641 \u0627\u0644\u0641\u0631\u064A\u062F (Slug) *</label>\n          <input type=\"text\" id=\"catSlug\" required placeholder=\"living-room\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none font-mono\" />\n        </div>\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0644\u0648\u0635\u0641</label>\n          <input type=\"text\" id=\"catDescription\" placeholder=\"\u0648\u0635\u0641 \u0645\u0648\u062C\u0632 \u0644\u0644\u0642\u0633\u0645...\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n        </div>\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">\u0631\u0627\u0628\u0637 \u0635\u0648\u0631\u0629 \u0627\u0644\u0642\u0633\u0645</label>\n          <input type=\"text\" id=\"catImageUrl\" placeholder=\"https://...\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none text-[11px]\" />\n        </div>\n        <div class=\"grid grid-cols-2 gap-4\">\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">\u062A\u0631\u062A\u064A\u0628 \u0627\u0644\u0638\u0647\u0648\u0631</label>\n            <input type=\"number\" id=\"catSortOrder\" value=\"1\" min=\"1\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n          </div>\n          <div class=\"flex items-center gap-2 pt-6\">\n            <input type=\"checkbox\" id=\"catIsFeatured\" checked class=\"rounded text-brand-600 w-4 h-4\" />\n            <label for=\"catIsFeatured\" class=\"font-bold text-slate-700 cursor-pointer\">\u0642\u0633\u0645 \u0645\u0645\u064A\u0632</label>\n          </div>\n        </div>\n\n        <div class=\"mt-6 flex items-center justify-end gap-3 pt-4 border-t border-slate-100\">\n          <button type=\"button\" onclick=\"closeCategoryModal()\" class=\"px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold\">\u0625\u0644\u063A\u0627\u0621</button>\n          <button type=\"submit\" class=\"px-5 py-2 bg-brand-600 hover:bg-brand-700 text-white rounded-xl font-bold shadow-sm\">\u062D\u0641\u0638 \u0627\u0644\u0642\u0633\u0645</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- 4. CUSTOMER / CLIENT (Add / Edit) MODAL -->\n  <div id=\"customerModal\" class=\"fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 hidden\">\n    <div class=\"bg-white rounded-2xl max-w-lg w-full p-6 shadow-xl text-right\">\n      <div class=\"flex items-center justify-between border-b border-slate-100 pb-3\">\n        <h3 class=\"font-bold text-base text-slate-900\" id=\"customerModalTitle\">\u0625\u0636\u0627\u0641\u0629 \u0639\u0645\u064A\u0644 \u062C\u062F\u064A\u062F</h3>\n        <button onclick=\"closeCustomerModal()\" class=\"text-slate-400 hover:text-slate-600 p-2 text-base\"><i class=\"fa-solid fa-xmark\"></i></button>\n      </div>\n\n      <form id=\"customerForm\" onsubmit=\"handleCustomerSubmit(event)\" class=\"mt-4 space-y-4 text-xs\">\n        <input type=\"hidden\" id=\"custEditId\" value=\"\" />\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0644\u0627\u0633\u0645 \u0627\u0644\u0643\u0627\u0645\u0644 *</label>\n          <input type=\"text\" id=\"custName\" required placeholder=\"\u0633\u0627\u0631\u0629 \u0623\u062D\u0645\u062F \u0645\u062D\u0645\u0648\u062F\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n        </div>\n        <div class=\"grid grid-cols-2 gap-4\">\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">\u0631\u0642\u0645 \u0627\u0644\u0647\u0627\u062A\u0641 (\u0645\u062D\u0645\u0648\u0644) *</label>\n            <input type=\"text\" id=\"custPhone\" required placeholder=\"01012345678\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none font-mono\" />\n          </div>\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0644\u0628\u0631\u064A\u062F \u0627\u0644\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A</label>\n            <input type=\"email\" id=\"custEmail\" placeholder=\"client@example.com\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n          </div>\n        </div>\n        <div class=\"grid grid-cols-2 gap-4\">\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0644\u0645\u062D\u0627\u0641\u0638\u0629</label>\n            <input type=\"text\" id=\"custGovernorate\" placeholder=\"\u0627\u0644\u0642\u0627\u0647\u0631\u0629\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n          </div>\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0644\u0645\u062F\u064A\u0646\u0629 / \u0627\u0644\u062D\u064A</label>\n            <input type=\"text\" id=\"custCity\" placeholder=\"\u0645\u062F\u064A\u0646\u0629 \u0646\u0635\u0631\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n          </div>\n        </div>\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u062A\u0641\u0635\u064A\u0644\u064A</label>\n          <input type=\"text\" id=\"custAddress\" placeholder=\"\u0627\u0644\u0634\u0627\u0631\u0639\u060C \u0631\u0642\u0645 \u0627\u0644\u0639\u0645\u0627\u0631\u0629\u060C \u0627\u0644\u0634\u0642\u0629...\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n        </div>\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">\u0645\u0644\u0627\u062D\u0638\u0627\u062A \u0627\u0644\u0639\u0645\u064A\u0644</label>\n          <input type=\"text\" id=\"custNotes\" placeholder=\"\u0645\u0644\u0627\u062D\u0638\u0627\u062A \u062A\u0641\u0636\u064A\u0644\u0627\u062A \u0627\u0644\u062A\u0633\u0644\u064A\u0645...\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n        </div>\n\n        <div class=\"mt-6 flex items-center justify-end gap-3 pt-4 border-t border-slate-100\">\n          <button type=\"button\" onclick=\"closeCustomerModal()\" class=\"px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold\">\u0625\u0644\u063A\u0627\u0621</button>\n          <button type=\"submit\" class=\"px-5 py-2 bg-brand-600 hover:bg-brand-700 text-white rounded-xl font-bold shadow-sm\">\u062D\u0641\u0638 \u0627\u0644\u0639\u0645\u064A\u0644 \u0639\u0644\u0649 Supabase</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- 5. EXPENSE (Add) MODAL -->\n  <div id=\"expenseModal\" class=\"fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 hidden\">\n    <div class=\"bg-white rounded-2xl max-w-md w-full p-6 shadow-xl text-right\">\n      <div class=\"flex items-center justify-between border-b border-slate-100 pb-3\">\n        <h3 class=\"font-bold text-base text-slate-900\">\u0625\u0636\u0627\u0641\u0629 \u0628\u0646\u062F \u0645\u0635\u0631\u0648\u0641 \u062C\u062F\u064A\u062F</h3>\n        <button onclick=\"closeExpenseModal()\" class=\"text-slate-400 hover:text-slate-600 p-2 text-base\"><i class=\"fa-solid fa-xmark\"></i></button>\n      </div>\n\n      <form id=\"expenseForm\" onsubmit=\"handleExpenseSubmit(event)\" class=\"mt-4 space-y-4 text-xs\">\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">\u0628\u064A\u0627\u0646 / \u0628\u0646\u062F \u0627\u0644\u0645\u0635\u0631\u0648\u0641 *</label>\n          <input type=\"text\" id=\"expTitle\" required placeholder=\"\u0645\u062B\u0627\u0644: \u0634\u0631\u0627\u0621 \u0623\u0642\u0645\u0634\u0629 \u0644\u064A\u0643\u0631\u0627 \u062C\u0627\u0643\u0627\u0631 \u062A\u0631\u0643\u064A\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n        </div>\n        <div class=\"grid grid-cols-2 gap-4\">\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0644\u0645\u0628\u0644\u063A (\u062C.\u0645) *</label>\n            <input type=\"number\" id=\"expAmount\" required min=\"1\" step=\"0.5\" placeholder=\"1500\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none font-bold\" />\n          </div>\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0644\u062A\u0635\u0646\u064A\u0641 *</label>\n            <select id=\"expCategory\" required class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none font-semibold\">\n              <option value=\"\u062E\u0627\u0645\u0627\u062A_\u0648\u062A\u0641\u0635\u064A\u0644\">\u062E\u0627\u0645\u0627\u062A \u0648\u062A\u0641\u0635\u064A\u0644 \u0623\u0642\u0645\u0634\u0629</option>\n              <option value=\"\u0628\u0636\u0627\u0639\u0629\">\u0634\u0631\u0627\u0621 \u0628\u0636\u0627\u0639\u0629</option>\n              <option value=\"\u0634\u062D\u0646\">\u062A\u0643\u0627\u0644\u064A\u0641 \u0634\u062D\u0646 \u0648\u0646\u0642\u0644</option>\n              <option value=\"\u062A\u0633\u0648\u064A\u0642\">\u062A\u0633\u0648\u064A\u0642 \u0648\u0625\u0639\u0644\u0627\u0646\u0627\u062A</option>\n              <option value=\"\u0625\u064A\u062C\u0627\u0631_\u0648\u0645\u0635\u0627\u0631\u064A\u0641\">\u0625\u064A\u062C\u0627\u0631 \u0648\u0645\u0635\u0627\u0631\u064A\u0641 \u062A\u0634\u063A\u064A\u0644</option>\n              <option value=\"\u0623\u062E\u0631\u0649\">\u0623\u062E\u0631\u0649</option>\n            </select>\n          </div>\n        </div>\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">\u0645\u0644\u0627\u062D\u0638\u0627\u062A \u0625\u0636\u0627\u0641\u064A\u0629</label>\n          <input type=\"text\" id=\"expNotes\" placeholder=\"\u0645\u0644\u0627\u062D\u0638\u0627\u062A \u062A\u0648\u062B\u064A\u0642 \u0627\u0644\u0641\u0627\u062A\u0648\u0631\u0629...\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n        </div>\n\n        <div class=\"mt-6 flex items-center justify-end gap-3 pt-4 border-t border-slate-100\">\n          <button type=\"button\" onclick=\"closeExpenseModal()\" class=\"px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold\">\u0625\u0644\u063A\u0627\u0621</button>\n          <button type=\"submit\" class=\"px-5 py-2 bg-rose-600 hover:bg-rose-700 text-white rounded-xl font-bold shadow-sm\">\u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u0645\u0635\u0631\u0648\u0641</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- 6. STAFF / ROLES (Add / Edit) MODAL -->\n  <div id=\"staffModal\" class=\"fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 hidden\">\n    <div class=\"bg-white rounded-2xl max-w-lg w-full p-6 max-h-[90vh] overflow-y-auto custom-scrollbar shadow-xl text-right\">\n      <div class=\"flex items-center justify-between border-b border-slate-100 pb-3\">\n        <h3 class=\"font-bold text-base text-slate-900\" id=\"staffModalTitle\">\u0625\u0636\u0627\u0641\u0629 \u0645\u0634\u0631\u0641 \u0648\u062A\u062D\u062F\u064A\u062F \u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0627\u062A</h3>\n        <button onclick=\"closeStaffModal()\" class=\"text-slate-400 hover:text-slate-600 p-2 text-base\"><i class=\"fa-solid fa-xmark\"></i></button>\n      </div>\n\n      <form id=\"staffForm\" onsubmit=\"handleStaffSubmit(event)\" class=\"mt-4 space-y-4 text-xs\">\n        <input type=\"hidden\" id=\"staffEditId\" value=\"\" />\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0644\u0627\u0633\u0645 \u0627\u0644\u0643\u0627\u0645\u0644 \u0644\u0644\u0645\u0634\u0631\u0641 *</label>\n          <input type=\"text\" id=\"staffName\" required placeholder=\"\u0623\u062D\u0645\u062F \u0633\u0639\u064A\u062F\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n        </div>\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0644\u0628\u0631\u064A\u062F \u0627\u0644\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A *</label>\n          <input type=\"email\" id=\"staffEmail\" required placeholder=\"staff@zahra-store.com\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n        </div>\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 <span id=\"staffPasswordHint\" class=\"text-slate-400 font-normal\"></span></label>\n          <input type=\"password\" id=\"staffPassword\" minlength=\"6\" placeholder=\"******\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n        </div>\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">\u0642\u0627\u0644\u0628 \u0627\u0644\u062F\u0648\u0631 \u0648\u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0627\u062A (Role Template) *</label>\n          <select id=\"staffRole\" required onchange=\"handleStaffRoleChange(this.value)\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none font-semibold\">\n            <option value=\"ADMIN\">\u0645\u062F\u064A\u0631 \u0639\u0627\u0645 (ADMIN) - \u0643\u0627\u0645\u0644 \u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0627\u062A \u0648\u0627\u0644\u0645\u0627\u0644\u064A\u0629 (9 \u0623\u0642\u0633\u0627\u0645)</option>\n            <option value=\"MANAGER\">\u0645\u0634\u0631\u0641 \u0639\u0645\u0644\u064A\u0627\u062A (MANAGER) - \u0645\u0646\u062A\u062C\u0627\u062A\u060C \u0623\u0642\u0633\u0627\u0645\u060C \u0637\u0644\u0628\u0627\u062A\u060C \u0643\u0631\u0627\u0633\u064A\u060C \u0639\u0645\u0644\u0627\u0621\u060C \u0634\u062D\u0646 (7 \u0623\u0642\u0633\u0627\u0645)</option>\n            <option value=\"SUPPORT\">\u062E\u062F\u0645\u0629 \u0639\u0645\u0644\u0627\u0621 (SUPPORT) - \u0645\u062A\u0627\u0628\u0639\u0629 \u0627\u0644\u0637\u0644\u0628\u0627\u062A \u0648\u062A\u0641\u0635\u064A\u0644 \u0627\u0644\u0643\u0631\u0627\u0633\u064A \u0641\u0642\u0637 (3 \u0623\u0642\u0633\u0627\u0645)</option>\n            <option value=\"CUSTOM\">\u0635\u0644\u0627\u062D\u064A\u0627\u062A \u0645\u062E\u0635\u0635\u0629 (CUSTOM) - \u062A\u062D\u062F\u064A\u062F \u064A\u062F\u0648\u064A \u0644\u0644\u0623\u0642\u0633\u0627\u0645</option>\n          </select>\n        </div>\n\n        <!-- Permissions Checklist Matrix -->\n        <div class=\"bg-slate-50 p-3.5 rounded-xl border border-slate-200 space-y-2.5\">\n          <div class=\"flex items-center justify-between\">\n            <span class=\"font-bold text-slate-800\">\u0627\u0644\u0623\u0642\u0633\u0627\u0645 \u0627\u0644\u0645\u0635\u0631\u062D \u0644\u0647 \u0628\u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064A\u0647\u0627:</span>\n            <span id=\"perm-selected-count\" class=\"text-[10px] bg-brand-100 text-brand-700 font-bold px-2 py-0.5 rounded-full\">9 / 9</span>\n          </div>\n          <div class=\"grid grid-cols-2 gap-2 text-[11px]\" id=\"permissionsChecklistGrid\">\n            <label class=\"flex items-center gap-2 p-2 bg-white rounded-lg border border-slate-200 cursor-pointer hover:border-brand-300\">\n              <input type=\"checkbox\" id=\"perm-overview\" value=\"overview\" onchange=\"updateSelectedPermsCount()\" checked class=\"rounded text-brand-600 w-3.5 h-3.5\" />\n              <span>\uD83D\uDCCA \u0646\u0638\u0631\u0629 \u0639\u0627\u0645\u0629</span>\n            </label>\n            <label class=\"flex items-center gap-2 p-2 bg-white rounded-lg border border-slate-200 cursor-pointer hover:border-brand-300\">\n              <input type=\"checkbox\" id=\"perm-products\" value=\"products\" onchange=\"updateSelectedPermsCount()\" checked class=\"rounded text-brand-600 w-3.5 h-3.5\" />\n              <span>\uD83C\uDFF7\uFE0F \u0627\u0644\u0645\u0646\u062A\u062C\u0627\u062A</span>\n            </label>\n            <label class=\"flex items-center gap-2 p-2 bg-white rounded-lg border border-slate-200 cursor-pointer hover:border-brand-300\">\n              <input type=\"checkbox\" id=\"perm-categories\" value=\"categories\" onchange=\"updateSelectedPermsCount()\" checked class=\"rounded text-brand-600 w-3.5 h-3.5\" />\n              <span>\uD83D\uDCC1 \u0627\u0644\u0623\u0642\u0633\u0627\u0645</span>\n            </label>\n            <label class=\"flex items-center gap-2 p-2 bg-white rounded-lg border border-slate-200 cursor-pointer hover:border-brand-300\">\n              <input type=\"checkbox\" id=\"perm-orders\" value=\"orders\" onchange=\"updateSelectedPermsCount()\" checked class=\"rounded text-brand-600 w-3.5 h-3.5\" />\n              <span>\uD83D\uDCE6 \u0627\u0644\u0637\u0644\u0628\u0627\u062A</span>\n            </label>\n            <label class=\"flex items-center gap-2 p-2 bg-white rounded-lg border border-slate-200 cursor-pointer hover:border-brand-300\">\n              <input type=\"checkbox\" id=\"perm-custom_chairs\" value=\"custom_chairs\" onchange=\"updateSelectedPermsCount()\" checked class=\"rounded text-brand-600 w-3.5 h-3.5\" />\n              <span>\uD83E\uDE91 \u0643\u0631\u0627\u0633\u064A \u0639\u0645\u0648\u0644\u0629</span>\n            </label>\n            <label class=\"flex items-center gap-2 p-2 bg-white rounded-lg border border-slate-200 cursor-pointer hover:border-brand-300\">\n              <input type=\"checkbox\" id=\"perm-customers\" value=\"customers\" onchange=\"updateSelectedPermsCount()\" checked class=\"rounded text-brand-600 w-3.5 h-3.5\" />\n              <span>\uD83D\uDC65 \u0627\u0644\u0639\u0645\u0644\u0627\u0621 CRM</span>\n            </label>\n            <label class=\"flex items-center gap-2 p-2 bg-white rounded-lg border border-slate-200 cursor-pointer hover:border-brand-300\">\n              <input type=\"checkbox\" id=\"perm-expenses\" value=\"expenses\" onchange=\"updateSelectedPermsCount()\" checked class=\"rounded text-brand-600 w-3.5 h-3.5\" />\n              <span>\uD83E\uDDFE \u0627\u0644\u0645\u0627\u0644\u064A\u0629 \u0648\u0627\u0644\u0623\u0631\u0628\u0627\u062D</span>\n            </label>\n            <label class=\"flex items-center gap-2 p-2 bg-white rounded-lg border border-slate-200 cursor-pointer hover:border-brand-300\">\n              <input type=\"checkbox\" id=\"perm-shipping\" value=\"shipping\" onchange=\"updateSelectedPermsCount()\" checked class=\"rounded text-brand-600 w-3.5 h-3.5\" />\n              <span>\uD83D\uDE9A \u0627\u0644\u0634\u062D\u0646</span>\n            </label>\n            <label class=\"flex items-center gap-2 p-2 bg-white rounded-lg border border-slate-200 cursor-pointer hover:border-brand-300 col-span-2\">\n              <input type=\"checkbox\" id=\"perm-staff\" value=\"staff\" onchange=\"updateSelectedPermsCount()\" checked class=\"rounded text-brand-600 w-3.5 h-3.5\" />\n              <span>\uD83D\uDEE1\uFE0F \u0627\u0644\u0645\u0634\u0631\u0641\u064A\u0646 \u0648\u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0627\u062A</span>\n            </label>\n          </div>\n        </div>\n\n        <div class=\"flex items-center gap-2 pt-1\">\n          <input type=\"checkbox\" id=\"staffIsActive\" checked class=\"rounded text-brand-600 w-4 h-4\" />\n          <label for=\"staffIsActive\" class=\"font-bold text-slate-700 cursor-pointer\">\u062D\u0633\u0627\u0628 \u0646\u0634\u0637 \u0648\u0645\u0641\u0639\u0651\u0644</label>\n        </div>\n\n        <div class=\"mt-6 flex items-center justify-end gap-3 pt-4 border-t border-slate-100\">\n          <button type=\"button\" onclick=\"closeStaffModal()\" class=\"px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold\">\u0625\u0644\u063A\u0627\u0621</button>\n          <button type=\"submit\" id=\"staffSubmitBtn\" class=\"px-5 py-2 bg-brand-600 hover:bg-brand-700 text-white rounded-xl font-bold shadow-sm\">\u062D\u0641\u0638 \u0627\u0644\u0645\u0634\u0631\u0641</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- 7. ORDER DETAILS / INVOICE MODAL -->\n  <div id=\"orderModal\" class=\"fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 hidden\">\n    <div class=\"bg-white rounded-2xl max-w-2xl w-full p-6 max-h-[90vh] overflow-y-auto custom-scrollbar shadow-xl text-right\">\n      <div class=\"flex items-center justify-between border-b border-slate-100 pb-3\">\n        <div>\n          <h3 class=\"font-bold text-base text-slate-900\" id=\"modalOrderNumber\">\u062A\u0641\u0627\u0635\u064A\u0644 \u0627\u0644\u0637\u0644\u0628</h3>\n          <span class=\"text-xs text-slate-400\" id=\"modalOrderDate\"></span>\n        </div>\n        <button onclick=\"closeOrderModal()\" class=\"text-slate-400 hover:text-slate-600 p-2 text-base\"><i class=\"fa-solid fa-xmark\"></i></button>\n      </div>\n\n      <div class=\"mt-4 space-y-4 text-xs\" id=\"modalOrderContent\"></div>\n\n      <div class=\"mt-6 flex items-center justify-between pt-4 border-t border-slate-100\">\n        <div class=\"flex items-center gap-2\">\n          <button onclick=\"window.print()\" class=\"px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold flex items-center gap-2\">\n            <i class=\"fa-solid fa-print\"></i>\n            \u0637\u0628\u0627\u0639\u0629 \u0627\u0644\u0628\u0648\u0644\u064A\u0635\u0629\n          </button>\n          <button id=\"btnDeleteCurrentOrder\" onclick=\"deleteCurrentOrder()\" class=\"px-3 py-2 bg-rose-50 hover:bg-rose-100 text-rose-700 rounded-xl font-bold flex items-center gap-1\">\n            <i class=\"fa-solid fa-trash-can\"></i>\n            \u062D\u0630\u0641 \u0627\u0644\u0637\u0644\u0628\n          </button>\n        </div>\n        <button onclick=\"closeOrderModal()\" class=\"px-4 py-2 bg-brand-600 hover:bg-brand-700 text-white rounded-xl font-bold\">\u0625\u063A\u0644\u0627\u0642</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- 8. IMAGE ZOOM PREVIEW MODAL -->\n  <div id=\"imageModal\" class=\"fixed inset-0 bg-slate-950/80 backdrop-blur-md z-50 flex items-center justify-center p-4 hidden\">\n    <div class=\"relative max-w-3xl w-full flex flex-col items-center\">\n      <button onclick=\"closeImageModal()\" class=\"absolute -top-10 left-0 text-white hover:text-rose-400 text-2xl p-2\"><i class=\"fa-solid fa-xmark\"></i></button>\n      <img id=\"modalPreviewImage\" src=\"\" alt=\"\u0635\u0648\u0631\u0629 \u0627\u0644\u0643\u0631\u0633\u064A \u0627\u0644\u0645\u0631\u0641\u0648\u0639\u0629\" class=\"max-h-[80vh] w-auto rounded-2xl shadow-2xl border-2 border-white/20 object-contain\" />\n      <div class=\"text-white text-xs mt-3 text-center\" id=\"modalImageCaption\">\u0635\u0648\u0631\u0629 \u0627\u0644\u0643\u0631\u0633\u064A \u0627\u0644\u0645\u0631\u0641\u0648\u0639\u0629 \u0645\u0646 \u0627\u0644\u0639\u0645\u064A\u0644 \u0644\u0645\u0642\u0627\u0633\u0627\u062A \u0627\u0644\u062A\u0641\u0635\u064A\u0644</div>\n    </div>\n  </div>\n\n  <!-- 9. PERMISSION (Add / Edit) MODAL -->\n  <div id=\"permissionModal\" class=\"fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 hidden\">\n    <div class=\"bg-white rounded-2xl max-w-md w-full p-6 shadow-xl text-right\">\n      <div class=\"flex items-center justify-between border-b border-slate-100 pb-3\">\n        <h3 class=\"font-bold text-base text-slate-900\" id=\"permModalTitle\">\u0625\u0636\u0627\u0641\u0629 \u0635\u0644\u0627\u062D\u064A\u0629 \u062C\u062F\u064A\u062F\u0629 \u0644\u0644\u0646\u0638\u0627\u0645</h3>\n        <button onclick=\"closePermissionModal()\" class=\"text-slate-400 hover:text-slate-600 p-2 text-base\"><i class=\"fa-solid fa-xmark\"></i></button>\n      </div>\n\n      <form id=\"permissionForm\" onsubmit=\"handlePermissionSubmit(event)\" class=\"mt-4 space-y-4 text-xs\">\n        <input type=\"hidden\" id=\"permEditId\" value=\"\" />\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0644\u0645\u0639\u0631\u0641 \u0627\u0644\u0628\u0631\u0645\u062C\u064A \u0627\u0644\u0641\u0631\u064A\u062F (Code Key) *</label>\n          <input type=\"text\" id=\"permKey\" required placeholder=\"\u0645\u062B\u0627\u0644: coupons \u0623\u0648 reports\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none font-mono text-left\" />\n          <span class=\"text-[10px] text-slate-400\">\u062D\u0631\u0648\u0641 \u0625\u0646\u062C\u0644\u064A\u0632\u064A\u0629 \u0635\u063A\u064A\u0631\u0629 \u0628\u062F\u0648\u0646 \u0645\u0633\u0627\u0641\u0627\u062A (e.g. coupons, notifications)</span>\n        </div>\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0633\u0645 \u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0629 \u0628\u0627\u0644\u0639\u0631\u0628\u064A\u0629 *</label>\n          <input type=\"text\" id=\"permNameAr\" required placeholder=\"\u0645\u062B\u0627\u0644: \u0625\u062F\u0627\u0631\u0629 \u0643\u0648\u0628\u0648\u0646\u0627\u062A \u0627\u0644\u062E\u0635\u0645 \u0648\u0627\u0644\u0639\u0631\u0648\u0636\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n        </div>\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">\u0627\u0644\u0642\u0633\u0645 \u0623\u0648 \u0627\u0644\u0648\u062D\u062F\u0629 (Module) *</label>\n          <input type=\"text\" id=\"permModule\" required placeholder=\"marketing \u0623\u0648 coupons\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none font-mono text-left\" />\n        </div>\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">\u0623\u064A\u0642\u0648\u0646\u0629 FontAwesome</label>\n          <input type=\"text\" id=\"permIcon\" value=\"fa-shield-halved\" placeholder=\"fa-tag \u0623\u0648 fa-chart-line\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none font-mono text-left\" />\n        </div>\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">\u0648\u0635\u0641 \u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0629</label>\n          <textarea id=\"permDescription\" rows=\"2\" placeholder=\"\u0648\u0635\u0641 \u0645\u0648\u062C\u0632 \u0644\u0644\u0645\u0647\u0627\u0645 \u0648\u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0627\u062A \u0627\u0644\u0645\u0633\u0645\u0648\u062D\u0629...\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\"></textarea>\n        </div>\n\n        <div class=\"mt-6 flex items-center justify-end gap-3 pt-4 border-t border-slate-100\">\n          <button type=\"button\" onclick=\"closePermissionModal()\" class=\"px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold\">\u0625\u0644\u063A\u0627\u0621</button>\n          <button type=\"submit\" id=\"permSubmitBtn\" class=\"px-5 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl font-bold shadow-sm\">\u062D\u0641\u0638 \u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0629</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- Toast Notification -->\n  <div id=\"toast\" class=\"fixed bottom-6 left-6 z-[110] bg-slate-900 text-white text-xs px-4 py-3 rounded-xl shadow-xl flex items-center gap-3 transition-transform duration-300 translate-y-24 opacity-0 pointer-events-none\">\n    <i id=\"toastIcon\" class=\"fa-solid fa-circle-check text-emerald-400\"></i>\n    <span id=\"toastMessage\">\u062A\u0645 \u0627\u0644\u0625\u062C\u0631\u0627\u0621 \u0628\u0646\u062C\u0627\u062D</span>\n  </div>\n\n  <!-- Main JavaScript App -->\n  <script>\n    const API_BASE = '/api';\n    let currentToken = localStorage.getItem('zahra_admin_token') || '';\n    let currentUser = null;\n    let currentTab = 'overview';\n    let categoriesList = [];\n    let productsList = [];\n    let ordersData = [];\n    let customersData = [];\n    let expensesData = [];\n    let staffData = [];\n    let systemPermissions = [];\n    let currentViewingOrderId = null;\n    let salesChartInstance = null;\n    let pendingDeleteCallback = null;\n\n    // Module Definitions & Default Role Templates\n    const ALL_MODULES_KEYS = ['overview', 'products', 'categories', 'orders', 'custom_chairs', 'customers', 'expenses', 'shipping', 'staff'];\n    const MODULE_NAMES = {\n      overview: '\u0646\u0638\u0631\u0629 \u0639\u0627\u0645\u0629',\n      products: '\u0627\u0644\u0645\u0646\u062A\u062C\u0627\u062A',\n      categories: '\u0627\u0644\u0623\u0642\u0633\u0627\u0645',\n      orders: '\u0627\u0644\u0637\u0644\u0628\u0627\u062A',\n      custom_chairs: '\u0643\u0631\u0627\u0633\u064A \u0639\u0645\u0648\u0644\u0629',\n      customers: '\u0627\u0644\u0639\u0645\u0644\u0627\u0621 CRM',\n      expenses: '\u0627\u0644\u0645\u0627\u0644\u064A\u0629 \u0648\u0627\u0644\u0623\u0631\u0628\u0627\u062D',\n      shipping: '\u0627\u0644\u0634\u062D\u0646',\n      staff: '\u0627\u0644\u0645\u0634\u0631\u0641\u064A\u0646 \u0648\u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0627\u062A'\n    };\n\n    const ROLE_PERMISSIONS_TEMPLATE = {\n      ADMIN: ['overview', 'products', 'categories', 'orders', 'custom_chairs', 'customers', 'expenses', 'shipping', 'staff'],\n      MANAGER: ['overview', 'products', 'categories', 'orders', 'custom_chairs', 'customers', 'shipping'],\n      SUPPORT: ['overview', 'orders', 'custom_chairs'],\n      CUSTOM: []\n    };\n\n    const MODULE_TAB_MAPPING = [\n      { mod: 'overview', tab: 'overview', btn: 'tab-btn-overview', panel: 'panel-overview' },\n      { mod: 'products', tab: 'products', btn: 'tab-btn-products', panel: 'panel-products' },\n      { mod: 'categories', tab: 'categories', btn: 'tab-btn-categories', panel: 'panel-categories' },\n      { mod: 'orders', tab: 'orders', btn: 'tab-btn-orders', panel: 'panel-orders' },\n      { mod: 'custom_chairs', tab: 'custom-chairs', btn: 'tab-btn-custom-chairs', panel: 'panel-custom-chairs' },\n      { mod: 'customers', tab: 'customers', btn: 'tab-btn-customers', panel: 'panel-customers' },\n      { mod: 'expenses', tab: 'expenses', btn: 'tab-btn-expenses', panel: 'panel-expenses' },\n      { mod: 'shipping', tab: 'shipping', btn: 'tab-btn-shipping', panel: 'panel-shipping' },\n      { mod: 'staff', tab: 'staff', btn: 'tab-btn-staff', panel: 'panel-staff' },\n    ];\n\n    function getUserPermissions() {\n      if (!currentUser) return [];\n      if (currentUser.role === 'ADMIN') return ROLE_PERMISSIONS_TEMPLATE.ADMIN;\n      if (currentUser.permissions && currentUser.permissions.length > 0) {\n        return currentUser.permissions;\n      }\n      return ROLE_PERMISSIONS_TEMPLATE[currentUser.role] || [];\n    }\n\n    function hasPermission(moduleKey) {\n      if (!currentUser) return false;\n      if (currentUser.role === 'ADMIN') return true;\n      const perms = getUserPermissions();\n      return perms.includes(moduleKey);\n    }\n\n    function applyRoleBasedUI() {\n      if (!currentUser) return;\n\n      MODULE_TAB_MAPPING.forEach(item => {\n        const allowed = hasPermission(item.mod);\n        const btn = document.getElementById(item.btn);\n        if (btn) {\n          if (allowed) btn.classList.remove('hidden');\n          else btn.classList.add('hidden');\n        }\n      });\n\n      // Financial widgets on overview (Hide revenue, expenses, net profit if user has no expenses permission)\n      const showExpenses = hasPermission('expenses');\n      ['kpi-card-revenue', 'kpi-card-expenses', 'kpi-card-net-profit'].forEach(id => {\n        const el = document.getElementById(id);\n        if (el) {\n          if (showExpenses) el.classList.remove('hidden');\n          else el.classList.add('hidden');\n        }\n      });\n\n      // Role badge in header\n      const roleLabel = currentUser.role === 'ADMIN' ? '\u0645\u062F\u064A\u0631 \u0639\u0627\u0645 (ADMIN)' : currentUser.role === 'MANAGER' ? '\u0645\u0634\u0631\u0641 \u0639\u0645\u0644\u064A\u0627\u062A (MANAGER)' : currentUser.role === 'SUPPORT' ? '\u062E\u062F\u0645\u0629 \u0639\u0645\u0644\u0627\u0621 (SUPPORT)' : '\u0645\u0634\u0631\u0641 \u0645\u062E\u0635\u0635 (CUSTOM)';\n      const roleDotColor = currentUser.role === 'ADMIN' ? 'bg-purple-500' : currentUser.role === 'MANAGER' ? 'bg-blue-500' : currentUser.role === 'SUPPORT' ? 'bg-teal-500' : 'bg-amber-500';\n      const roleBadgeEl = document.getElementById('userRoleBadge');\n      if (roleBadgeEl) {\n        roleBadgeEl.innerHTML = `<span class=\"w-1.5 h-1.5 rounded-full ${roleDotColor} animate-pulse\"></span> ${roleLabel}`;\n      }\n\n      // If current tab is hidden/unauthorized, switch automatically to the first allowed tab\n      const currentMapping = MODULE_TAB_MAPPING.find(m => m.tab === currentTab);\n      if (currentMapping && !hasPermission(currentMapping.mod)) {\n        const firstAllowed = MODULE_TAB_MAPPING.find(m => hasPermission(m.mod));\n        if (firstAllowed) {\n          switchTab(firstAllowed.tab);\n        }\n      }\n    }\n\n    // Toast Notification Helper\n    function showToast(msg, type = 'success') {\n      const toast = document.getElementById('toast');\n      const toastMsg = document.getElementById('toastMessage');\n      const toastIcon = document.getElementById('toastIcon');\n\n      toastMsg.textContent = msg;\n      if (type === 'success') {\n        toastIcon.className = 'fa-solid fa-circle-check text-emerald-400';\n      } else {\n        toastIcon.className = 'fa-solid fa-circle-exclamation text-rose-400';\n      }\n\n      toast.classList.remove('translate-y-24', 'opacity-0', 'pointer-events-none');\n      setTimeout(() => {\n        toast.classList.add('translate-y-24', 'opacity-0', 'pointer-events-none');\n      }, 3000);\n    }\n\n    // Auth Headers\n    function getHeaders(extraHeaders = {}) {\n      const headers = { 'Content-Type': 'application/json', ...extraHeaders };\n      if (currentToken) {\n        headers['Authorization'] = `Bearer ${currentToken}`;\n      }\n      return headers;\n    }\n\n    // Authentication Checks\n    async function checkAuth() {\n      if (!currentToken) {\n        showLoginScreen();\n        return false;\n      }\n      try {\n        const res = await fetch(`${API_BASE}/auth/me`, { headers: getHeaders() });\n        if (!res.ok) {\n          showLoginScreen();\n          return false;\n        }\n        currentUser = await res.json();\n        document.getElementById('userNameDisplay').textContent = currentUser.name || '\u0645\u062F\u064A\u0631 \u0645\u062A\u062C\u0631 \u0632\u0647\u0631\u0629';\n        document.getElementById('userAvatar').textContent = (currentUser.name || '\u0645').slice(0, 1);\n        applyRoleBasedUI();\n        hideLoginScreen();\n        return true;\n      } catch (e) {\n        showLoginScreen();\n        return false;\n      }\n    }\n\n    function showLoginScreen() {\n      document.getElementById('loginScreen').classList.remove('hidden');\n    }\n\n    function hideLoginScreen() {\n      document.getElementById('loginScreen').classList.add('hidden');\n    }\n\n    async function handleLoginSubmit(e) {\n      e.preventDefault();\n      const email = document.getElementById('loginEmail').value.trim();\n      const password = document.getElementById('loginPassword').value;\n\n      try {\n        const res = await fetch(`${API_BASE}/auth/login`, {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ email, password }),\n        });\n\n        if (res.ok) {\n          const data = await res.json();\n          currentToken = data.accessToken;\n          currentUser = data.user;\n          localStorage.setItem('zahra_admin_token', currentToken);\n          hideLoginScreen();\n          document.getElementById('userNameDisplay').textContent = currentUser.name || '\u0645\u062F\u064A\u0631 \u0645\u062A\u062C\u0631 \u0632\u0647\u0631\u0629';\n          document.getElementById('userAvatar').textContent = (currentUser.name || '\u0645').slice(0, 1);\n          applyRoleBasedUI();\n          showToast(`\u0645\u0631\u062D\u0628\u0627\u064B \u0628\u0643 ${currentUser.name}! \u062A\u0645 \u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u062F\u062E\u0648\u0644 \u0628\u0646\u062C\u0627\u062D`);\n          loadOverview();\n        } else {\n          showToast('\u0627\u0644\u0628\u0631\u064A\u062F \u0627\u0644\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A \u0623\u0648 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u063A\u064A\u0631 \u0635\u062D\u064A\u062D\u0629', 'error');\n        }\n      } catch (err) {\n        showToast('\u062A\u0639\u0630\u0631 \u0627\u0644\u0627\u062A\u0635\u0627\u0644 \u0628\u0627\u0644\u062E\u0627\u062F\u0645', 'error');\n      }\n    }\n\n    function handleLogout() {\n      localStorage.removeItem('zahra_admin_token');\n      currentToken = '';\n      currentUser = null;\n      showToast('\u062A\u0645 \u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u062E\u0631\u0648\u062C \u0628\u0646\u062C\u0627\u062D');\n      showLoginScreen();\n    }\n\n    function refreshCurrentTab() {\n      showToast('\u062C\u0627\u0631\u064A \u062A\u062D\u062F\u064A\u062B \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0645\u0646 Supabase...');\n      switchTab(currentTab);\n    }\n\n    // \u2500\u2500 CUSTOM IN-PLACE DELETE MODAL (Replaces browser confirm) \u2500\u2500\n    function openDeleteModal(title, desc, onConfirm) {\n      document.getElementById('delModalTitle').textContent = title;\n      document.getElementById('delModalDesc').textContent = desc;\n      pendingDeleteCallback = onConfirm;\n      document.getElementById('delModalConfirmBtn').onclick = () => {\n        if (pendingDeleteCallback) pendingDeleteCallback();\n        closeDeleteModal();\n      };\n      document.getElementById('deleteConfirmModal').classList.remove('hidden');\n    }\n\n    function closeDeleteModal() {\n      document.getElementById('deleteConfirmModal').classList.add('hidden');\n      pendingDeleteCallback = null;\n    }\n\n    // Tab Switcher with Strict RBAC Permissions Guard\n    function switchTab(tabId) {\n      const targetItem = MODULE_TAB_MAPPING.find(m => m.tab === tabId);\n      if (targetItem && !hasPermission(targetItem.mod)) {\n        showToast('\u0644\u064A\u0633 \u0644\u062F\u064A\u0643 \u0635\u0644\u0627\u062D\u064A\u0629 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0642\u0633\u0645', 'error');\n        const firstAllowed = MODULE_TAB_MAPPING.find(m => hasPermission(m.mod));\n        if (firstAllowed && firstAllowed.tab !== tabId) {\n          switchTab(firstAllowed.tab);\n        }\n        return;\n      }\n\n      currentTab = tabId;\n      MODULE_TAB_MAPPING.forEach(item => {\n        const panel = document.getElementById(item.panel);\n        const btn = document.getElementById(item.btn);\n        if (item.tab === tabId) {\n          if (panel) panel.classList.remove('hidden');\n          if (btn) {\n            btn.classList.add('text-brand-700', 'bg-brand-50');\n            btn.classList.remove('text-slate-600', 'hover:bg-slate-50');\n          }\n        } else {\n          if (panel) panel.classList.add('hidden');\n          if (btn) {\n            btn.classList.remove('text-brand-700', 'bg-brand-50');\n            btn.classList.add('text-slate-600', 'hover:bg-slate-50');\n          }\n        }\n      });\n\n      if (tabId === 'overview') loadOverview();\n      else if (tabId === 'products') loadProducts();\n      else if (tabId === 'categories') loadCategories();\n      else if (tabId === 'orders') loadOrders();\n      else if (tabId === 'custom-chairs') loadChairRequests();\n      else if (tabId === 'customers') loadCustomers();\n      else if (tabId === 'expenses') loadExpenses();\n      else if (tabId === 'shipping') loadShippingZones();\n      else if (tabId === 'staff') loadStaffUsers();\n    }\n\n    // \u2500\u2500 1. OVERVIEW & FINANCIALS \u2500\u2500\n    async function loadOverview() {\n      try {\n        const res = await fetch(`${API_BASE}/admin/overview`, { headers: getHeaders() });\n        if (!res.ok) return;\n        const data = await res.json();\n\n        document.getElementById('kpi-revenue').textContent = `${(data.totalRevenue || 0).toLocaleString()} \u062C.\u0645`;\n        document.getElementById('kpi-expenses').textContent = `${(data.totalExpenses || 0).toLocaleString()} \u062C.\u0645`;\n        document.getElementById('kpi-net-profit').textContent = `${(data.netProfit || 0).toLocaleString()} \u062C.\u0645`;\n        document.getElementById('kpi-orders').textContent = data.totalOrders || 0;\n        document.getElementById('kpi-pending-label').textContent = `${data.pendingOrders || 0} \u0637\u0644\u0628 \u0645\u0639\u0644\u0642`;\n        document.getElementById('kpi-products').textContent = data.totalProducts || 0;\n        document.getElementById('kpi-clients').textContent = data.totalClients || 0;\n\n        // Live Sidebar Badges Synchronization\n        if (data.totalProducts !== undefined) {\n          const bp = document.getElementById('badge-products-count');\n          if (bp) bp.textContent = data.totalProducts;\n        }\n        if (data.totalCategories !== undefined) {\n          const bc = document.getElementById('badge-categories-count');\n          if (bc) bc.textContent = data.totalCategories;\n        }\n        if (data.totalClients !== undefined) {\n          const bcl = document.getElementById('badge-clients-count');\n          if (bcl) bcl.textContent = data.totalClients;\n        }\n        if (data.totalStaff !== undefined) {\n          const bs = document.getElementById('badge-staff-count');\n          if (bs) bs.textContent = data.totalStaff;\n        }\n\n        const bpo = document.getElementById('badge-pending-orders');\n        if (bpo) {\n          bpo.textContent = data.pendingOrders || 0;\n          if (data.pendingOrders > 0) bpo.classList.remove('hidden');\n          else bpo.classList.add('hidden');\n        }\n        const bnc = document.getElementById('badge-new-chairs');\n        if (bnc) {\n          bnc.textContent = data.customRequestsCount || 0;\n          if (data.customRequestsCount > 0) bnc.classList.remove('hidden');\n          else bnc.classList.add('hidden');\n        }\n\n        // Low stock list\n        const lowStockContainer = document.getElementById('low-stock-list');\n        lowStockContainer.innerHTML = '';\n        if (data.lowStockProducts && data.lowStockProducts.length > 0) {\n          data.lowStockProducts.forEach(item => {\n            const div = document.createElement('div');\n            div.className = 'flex items-center justify-between p-2.5 rounded-xl bg-slate-50 border border-slate-100 text-xs';\n            div.innerHTML = `\n              <span class=\"font-medium text-slate-800\">${item.name_ar}</span>\n              <span class=\"px-2 py-0.5 rounded-full font-bold ${item.stock_quantity <= 5 ? 'bg-rose-100 text-rose-700' : 'bg-amber-100 text-amber-700'}\">\n                \u0645\u062A\u0628\u0642\u064A ${item.stock_quantity}\n              </span>\n            `;\n            lowStockContainer.appendChild(div);\n          });\n        } else {\n          lowStockContainer.innerHTML = '<div class=\"text-xs text-slate-400 py-3 text-center\">\u0644\u0627 \u062A\u0648\u062C\u062F \u0645\u0646\u062A\u062C\u0627\u062A \u0645\u0646\u062E\u0641\u0636\u0629 \u0627\u0644\u0645\u062E\u0632\u0648\u0646</div>';\n        }\n\n        // Recent Orders\n        const ordersTbody = document.getElementById('overview-orders-tbody');\n        ordersTbody.innerHTML = '';\n        (data.recentOrders || []).forEach(o => {\n          const tr = document.createElement('tr');\n          tr.className = 'hover:bg-slate-50/70 transition-colors';\n          tr.innerHTML = `\n            <td class=\"p-3 font-bold text-brand-700\">${o.order_number || o.orderNumber}</td>\n            <td class=\"p-3\">${o.customer_name || (o.customer ? o.customer.firstName + ' ' + o.customer.lastName : '')}</td>\n            <td class=\"p-3\">${o.governorate || o.address?.governorate || '-'}</td>\n            <td class=\"p-3 font-semibold\">${o.total_amount || o.total} \u062C.\u0645</td>\n            <td class=\"p-3\">${renderStatusBadge(o.status)}</td>\n            <td class=\"p-3 text-slate-400 font-mono\">${new Date(o.created_at || o.createdAt).toLocaleDateString('ar-EG')}</td>\n          `;\n          ordersTbody.appendChild(tr);\n        });\n\n        renderSalesChart(data.salesChart || []);\n      } catch (e) {\n        console.warn('Overview error:', e);\n      }\n    }\n\n    function renderSalesChart(chartData) {\n      const ctx = document.getElementById('salesChartCanvas').getContext('2d');\n      if (salesChartInstance) salesChartInstance.destroy();\n\n      salesChartInstance = new Chart(ctx, {\n        type: 'line',\n        data: {\n          labels: chartData.map(d => d.day),\n          datasets: [{\n            label: '\u0627\u0644\u0645\u0628\u064A\u0639\u0627\u062A \u0627\u0644\u064A\u0648\u0645\u064A\u0629 (\u062C.\u0645)',\n            data: chartData.map(d => d.sales),\n            borderColor: '#db2777',\n            backgroundColor: 'rgba(219, 39, 119, 0.1)',\n            fill: true,\n            tension: 0.4,\n            borderWidth: 3,\n            pointBackgroundColor: '#be185d',\n            pointRadius: 4,\n          }]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: { legend: { display: false } },\n          scales: {\n            y: { beginAtZero: true, grid: { color: '#f1f5f9' }, ticks: { font: { family: 'Cairo' } } },\n            x: { grid: { display: false }, ticks: { font: { family: 'Cairo' } } }\n          }\n        }\n      });\n    }\n\n    function renderStatusBadge(status) {\n      const map = {\n        pending: { text: '\u0645\u0639\u0644\u0642', class: 'bg-amber-100 text-amber-800' },\n        confirmed: { text: '\u0645\u0624\u0643\u062F', class: 'bg-blue-100 text-blue-800' },\n        processing: { text: '\u0642\u064A\u062F \u0627\u0644\u062A\u062C\u0647\u064A\u0632', class: 'bg-purple-100 text-purple-800' },\n        shipped: { text: '\u062A\u0645 \u0627\u0644\u0634\u062D\u0646', class: 'bg-indigo-100 text-indigo-800' },\n        delivered: { text: '\u062A\u0645 \u0627\u0644\u062A\u0633\u0644\u064A\u0645', class: 'bg-emerald-100 text-emerald-800' },\n        cancelled: { text: '\u0645\u0644\u063A\u064A', class: 'bg-rose-100 text-rose-800' },\n        new: { text: '\u062C\u062F\u064A\u062F', class: 'bg-rose-100 text-rose-800' },\n        contacted: { text: '\u062A\u0645 \u0627\u0644\u062A\u0648\u0627\u0635\u0644', class: 'bg-blue-100 text-blue-800' },\n        in_tailoring: { text: '\u062C\u0627\u0631\u064A \u0627\u0644\u062A\u0641\u0635\u064A\u0644', class: 'bg-amber-100 text-amber-800' },\n        completed: { text: '\u0645\u0643\u062A\u0645\u0644', class: 'bg-emerald-100 text-emerald-800' },\n      };\n      const info = map[status] || { text: status, class: 'bg-slate-100 text-slate-800' };\n      return `<span class=\"px-2 py-0.5 rounded-full text-[11px] font-bold ${info.class}\">${info.text}</span>`;\n    }\n\n    // \u2500\u2500 2. PRODUCTS \u2500\u2500\n    async function loadProducts() {\n      try {\n        const res = await fetch(`${API_BASE}/products`);\n        if (!res.ok) return;\n        productsList = await res.json();\n        document.getElementById('badge-products-count').textContent = productsList.length;\n\n        const tbody = document.getElementById('products-table-tbody');\n        tbody.innerHTML = '';\n        productsList.forEach(p => {\n          const tr = document.createElement('tr');\n          tr.className = 'hover:bg-slate-50/70 transition-colors';\n          const imgUrl = (p.images && p.images[0]) ? p.images[0].url : 'https://placehold.co/100x100?text=Zahra';\n          tr.innerHTML = `\n            <td class=\"p-3\">\n              <div class=\"flex items-center gap-3\">\n                <img src=\"${imgUrl}\" class=\"w-10 h-10 rounded-lg object-cover border border-slate-100\" />\n                <div>\n                  <div class=\"font-bold text-slate-900\">${p.name}</div>\n                  <div class=\"text-[10px] text-slate-400 font-mono\">${p.slug}</div>\n                </div>\n              </div>\n            </td>\n            <td class=\"p-3 text-slate-600\">${p.categoryName || p.category}</td>\n            <td class=\"p-3 font-bold text-slate-900\">${p.price} \u062C.\u0645</td>\n            <td class=\"p-3 text-slate-400\">${p.originalPrice ? p.originalPrice + ' \u062C.\u0645' : '-'}</td>\n            <td class=\"p-3\">${p.discount ? `<span class=\"bg-rose-100 text-rose-700 px-1.5 py-0.5 rounded font-bold text-[10px]\">${p.discount}%</span>` : '-'}</td>\n            <td class=\"p-3 font-semibold\">${p.stockCount ?? 10}</td>\n            <td class=\"p-3\">\n              <button onclick=\"toggleProductStock('${p.id}', ${!p.inStock})\" class=\"px-2.5 py-1 rounded-full text-[11px] font-bold transition-colors ${p.inStock ? 'bg-emerald-100 text-emerald-800 hover:bg-emerald-200' : 'bg-slate-200 text-slate-600 hover:bg-slate-300'}\">\n                ${p.inStock ? '\u0645\u062A\u0648\u0641\u0631' : '\u063A\u064A\u0631 \u0645\u062A\u0648\u0641\u0631'}\n              </button>\n            </td>\n            <td class=\"p-3 text-center\">\n              <div class=\"flex items-center justify-center gap-2\">\n                <button onclick=\"editProduct('${p.id}')\" class=\"p-1.5 text-slate-400 hover:text-brand-600 rounded\" title=\"\u062A\u0639\u062F\u064A\u0644\"><i class=\"fa-solid fa-pen-to-square\"></i></button>\n                <button onclick=\"confirmDeleteProduct('${p.id}', '${p.name}')\" class=\"p-1.5 text-slate-400 hover:text-rose-600 rounded\" title=\"\u062D\u0630\u0641\"><i class=\"fa-solid fa-trash-can\"></i></button>\n              </div>\n            </td>\n          `;\n          tbody.appendChild(tr);\n        });\n      } catch (e) {\n        console.warn('Products load error:', e);\n      }\n    }\n\n    async function toggleProductStock(id, inStock) {\n      try {\n        const res = await fetch(`${API_BASE}/products/${id}/stock`, {\n          method: 'PATCH',\n          headers: getHeaders(),\n          body: JSON.stringify({ inStock }),\n        });\n        if (res.ok) {\n          showToast('\u062A\u0645 \u062A\u062D\u062F\u064A\u062B \u062D\u0627\u0644\u0629 \u062A\u0648\u0641\u0631 \u0627\u0644\u0645\u0646\u062A\u062C');\n          loadProducts();\n        }\n      } catch (e) {\n        showToast('\u0641\u0634\u0644 \u0627\u0644\u062A\u062D\u062F\u064A\u062B', 'error');\n      }\n    }\n\n    async function populateCategoryDropdown(selectedSlug = '') {\n      if (categoriesList.length === 0) {\n        const res = await fetch(`${API_BASE}/categories`);\n        if (res.ok) categoriesList = await res.json();\n      }\n      const select = document.getElementById('prodCategory');\n      select.innerHTML = '';\n      categoriesList.forEach(c => {\n        const opt = document.createElement('option');\n        opt.value = c.slug;\n        opt.textContent = c.name || c.name_ar;\n        if (c.slug === selectedSlug) opt.selected = true;\n        select.appendChild(opt);\n      });\n    }\n\n    async function openProductModal() {\n      await populateCategoryDropdown();\n      document.getElementById('productForm').reset();\n      document.getElementById('prodEditId').value = '';\n      document.getElementById('productModalTitle').textContent = '\u0625\u0636\u0627\u0641\u0629 \u0645\u0646\u062A\u062C \u062C\u062F\u064A\u062F';\n      document.getElementById('prodSubmitBtn').textContent = '\u0625\u0636\u0627\u0641\u0629 \u0627\u0644\u0645\u0646\u062A\u062C \u0625\u0644\u0649 Supabase';\n      document.getElementById('prodImagePreviewContainer').classList.add('hidden');\n      document.getElementById('productModal').classList.remove('hidden');\n    }\n\n    async function editProduct(id) {\n      const prod = productsList.find(p => p.id === id);\n      if (!prod) return;\n\n      await populateCategoryDropdown(prod.category);\n      document.getElementById('prodEditId').value = prod.id;\n      document.getElementById('prodName').value = prod.name;\n      document.getElementById('prodSlug').value = prod.slug;\n      document.getElementById('prodPrice').value = prod.price;\n      document.getElementById('prodOriginalPrice').value = prod.originalPrice || '';\n      document.getElementById('prodDiscount').value = prod.discount || '';\n      document.getElementById('prodStock').value = prod.stockCount ?? 10;\n      document.getElementById('prodMaterial').value = prod.material || '';\n      document.getElementById('prodDescription').value = prod.description || '';\n      \n      const firstImg = prod.images && prod.images[0] ? prod.images[0].url : '';\n      document.getElementById('prodImageUrl').value = firstImg;\n      if (firstImg) {\n        document.getElementById('prodImagePreview').src = firstImg;\n        document.getElementById('prodImagePreviewContainer').classList.remove('hidden');\n      } else {\n        document.getElementById('prodImagePreviewContainer').classList.add('hidden');\n      }\n\n      document.getElementById('prodInStock').checked = prod.inStock;\n      document.getElementById('prodIsFeatured').checked = !!prod.isFeatured;\n      document.getElementById('prodIsOnSale').checked = !!prod.isOnSale;\n      document.getElementById('prodIsChairCover').checked = !!prod.isChairCover;\n\n      document.getElementById('productModalTitle').textContent = `\u062A\u0639\u062F\u064A\u0644 \u0627\u0644\u0645\u0646\u062A\u062C: ${prod.name}`;\n      document.getElementById('prodSubmitBtn').textContent = '\u062D\u0641\u0638 \u0627\u0644\u062A\u0639\u062F\u064A\u0644\u0627\u062A \u0639\u0644\u0649 Supabase';\n      document.getElementById('productModal').classList.remove('hidden');\n    }\n\n    function closeProductModal() {\n      document.getElementById('productModal').classList.add('hidden');\n    }\n\n    async function uploadProductImage() {\n      const fileInput = document.getElementById('prodImageFile');\n      if (!fileInput.files || fileInput.files.length === 0) {\n        showToast('\u064A\u0631\u062C\u0649 \u0627\u062E\u062A\u064A\u0627\u0631 \u0645\u0644\u0641 \u0635\u0648\u0631\u0629 \u0623\u0648\u0644\u0627\u064B', 'error');\n        return;\n      }\n      const formData = new FormData();\n      formData.append('file', fileInput.files[0]);\n\n      showToast('\u062C\u0627\u0631\u064A \u0627\u0644\u0631\u0641\u0639 \u0625\u0644\u0649 Supabase Storage...');\n      try {\n        const res = await fetch(`${API_BASE}/storage/upload?bucket=products`, {\n          method: 'POST',\n          headers: { 'Authorization': `Bearer ${currentToken}` },\n          body: formData,\n        });\n\n        if (res.ok) {\n          const data = await res.json();\n          document.getElementById('prodImageUrl').value = data.url;\n          document.getElementById('prodImagePreview').src = data.url;\n          document.getElementById('prodImagePreviewContainer').classList.remove('hidden');\n          showToast('\u062A\u0645 \u0631\u0641\u0639 \u0627\u0644\u0635\u0648\u0631\u0629 \u0628\u0646\u062C\u0627\u062D!');\n        } else {\n          showToast('\u0641\u0634\u0644 \u0631\u0641\u0639 \u0627\u0644\u0635\u0648\u0631\u0629', 'error');\n        }\n      } catch (e) {\n        showToast('\u062D\u062F\u062B \u062E\u0637\u0623 \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u0631\u0641\u0639', 'error');\n      }\n    }\n\n    async function handleProductSubmit(e) {\n      e.preventDefault();\n      const editId = document.getElementById('prodEditId').value;\n      const imageUrl = document.getElementById('prodImageUrl').value.trim();\n\n      const payload = {\n        name: document.getElementById('prodName').value.trim(),\n        slug: document.getElementById('prodSlug').value.trim(),\n        category: document.getElementById('prodCategory').value,\n        price: Number(document.getElementById('prodPrice').value),\n        originalPrice: document.getElementById('prodOriginalPrice').value ? Number(document.getElementById('prodOriginalPrice').value) : undefined,\n        discount: document.getElementById('prodDiscount').value ? Number(document.getElementById('prodDiscount').value) : undefined,\n        stockCount: Number(document.getElementById('prodStock').value),\n        material: document.getElementById('prodMaterial').value.trim() || undefined,\n        description: document.getElementById('prodDescription').value.trim(),\n        inStock: document.getElementById('prodInStock').checked,\n        isFeatured: document.getElementById('prodIsFeatured').checked,\n        isOnSale: document.getElementById('prodIsOnSale').checked,\n        isChairCover: document.getElementById('prodIsChairCover').checked,\n      };\n\n      if (imageUrl) payload.images = [{ url: imageUrl, alt: payload.name, is_primary: true }];\n\n      try {\n        const url = editId ? `${API_BASE}/products/${editId}` : `${API_BASE}/products`;\n        const method = editId ? 'PUT' : 'POST';\n        const res = await fetch(url, {\n          method,\n          headers: getHeaders(),\n          body: JSON.stringify(payload),\n        });\n\n        if (res.ok) {\n          showToast(editId ? '\u062A\u0645 \u062A\u062D\u062F\u064A\u062B \u0627\u0644\u0645\u0646\u062A\u062C \u0628\u0646\u062C\u0627\u062D' : '\u062A\u0645\u062A \u0625\u0636\u0627\u0641\u0629 \u0627\u0644\u0645\u0646\u062A\u062C \u0628\u0646\u062C\u0627\u062D');\n          closeProductModal();\n          loadProducts();\n        } else {\n          const err = await res.json();\n          showToast(`\u062E\u0637\u0623: ${err.message || '\u0641\u0634\u0644\u062A \u0627\u0644\u0639\u0645\u0644\u064A\u0629'}`, 'error');\n        }\n      } catch (e) {\n        showToast('\u062D\u062F\u062B \u062E\u0637\u0623 \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u062D\u0641\u0638', 'error');\n      }\n    }\n\n    function confirmDeleteProduct(id, name) {\n      openDeleteModal(\n        `\u062D\u0630\u0641 \u0627\u0644\u0645\u0646\u062A\u062C: ${name}`,\n        `\u0647\u0644 \u0623\u0646\u062A \u0645\u062A\u0623\u0643\u062F \u0645\u0646 \u0631\u063A\u0628\u062A\u0643 \u0641\u064A \u062D\u0630\u0641 \u0627\u0644\u0645\u0646\u062A\u062C \"${name}\" \u0646\u0647\u0627\u0626\u064A\u0627\u064B \u0645\u0646 \u0642\u0627\u0639\u062F\u0629 \u0628\u064A\u0627\u0646\u0627\u062A Supabase\u061F`,\n        async () => {\n          try {\n            const res = await fetch(`${API_BASE}/products/${id}`, {\n              method: 'DELETE',\n              headers: getHeaders(),\n            });\n            if (res.ok) {\n              showToast(`\u062A\u0645 \u062D\u0630\u0641 \u0627\u0644\u0645\u0646\u062A\u062C \"${name}\" \u0628\u0646\u062C\u0627\u062D`);\n              loadProducts();\n            } else {\n              showToast('\u0641\u0634\u0644 \u062D\u0630\u0641 \u0627\u0644\u0645\u0646\u062A\u062C', 'error');\n            }\n          } catch (e) {\n            showToast('\u062D\u062F\u062B \u062E\u0637\u0623 \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u062D\u0630\u0641', 'error');\n          }\n        }\n      );\n    }\n\n    // \u2500\u2500 3. CATEGORIES \u2500\u2500\n    async function loadCategories() {\n      try {\n        const res = await fetch(`${API_BASE}/categories`);\n        if (!res.ok) return;\n        categoriesList = await res.json();\n        document.getElementById('badge-categories-count').textContent = categoriesList.length;\n\n        const grid = document.getElementById('categories-grid');\n        grid.innerHTML = '';\n        categoriesList.forEach(c => {\n          const card = document.createElement('div');\n          card.className = 'bg-white rounded-2xl border border-slate-200 p-4 shadow-sm flex flex-col justify-between';\n          card.innerHTML = `\n            <div class=\"flex items-center gap-4\">\n              <img src=\"${c.image || c.image_url || 'https://placehold.co/80x80?text=Category'}\" class=\"w-16 h-16 rounded-xl object-cover border border-slate-100\" />\n              <div class=\"flex-1\">\n                <h3 class=\"font-bold text-sm text-slate-900\">${c.name || c.name_ar}</h3>\n                <div class=\"text-[10px] text-slate-400 font-mono\">${c.slug}</div>\n                <div class=\"text-[11px] text-slate-500 mt-1 line-clamp-1\">${c.description || ''}</div>\n              </div>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 flex items-center justify-between text-xs\">\n              <span class=\"text-brand-600 font-bold\">${c.productCount || 0} \u0645\u0646\u062A\u062C\u0627\u062A</span>\n              <div class=\"flex items-center gap-2\">\n                <button onclick=\"editCategory('${c.id}')\" class=\"p-1 text-slate-400 hover:text-brand-600\" title=\"\u062A\u0639\u062F\u064A\u0644\"><i class=\"fa-solid fa-pen-to-square\"></i></button>\n                <button onclick=\"confirmDeleteCategory('${c.id}', '${c.name || c.name_ar}')\" class=\"p-1 text-slate-400 hover:text-rose-600\" title=\"\u062D\u0630\u0641\"><i class=\"fa-solid fa-trash-can\"></i></button>\n              </div>\n            </div>\n          `;\n          grid.appendChild(card);\n        });\n      } catch (e) {\n        console.warn('Categories error:', e);\n      }\n    }\n\n    function openCategoryModal() {\n      document.getElementById('categoryForm').reset();\n      document.getElementById('catEditId').value = '';\n      document.getElementById('categoryModalTitle').textContent = '\u0625\u0636\u0627\u0641\u0629 \u0642\u0633\u0645 \u062C\u062F\u064A\u062F';\n      document.getElementById('categoryModal').classList.remove('hidden');\n    }\n\n    function editCategory(id) {\n      const cat = categoriesList.find(c => c.id === id);\n      if (!cat) return;\n\n      document.getElementById('catEditId').value = cat.id;\n      document.getElementById('catName').value = cat.name || cat.name_ar;\n      document.getElementById('catSlug').value = cat.slug;\n      document.getElementById('catDescription').value = cat.description || '';\n      document.getElementById('catImageUrl').value = cat.image || cat.image_url || '';\n      document.getElementById('catSortOrder').value = cat.sort_order || 1;\n      document.getElementById('catIsFeatured').checked = !!cat.featured || !!cat.is_featured;\n\n      document.getElementById('categoryModalTitle').textContent = `\u062A\u0639\u062F\u064A\u0644 \u0642\u0633\u0645: ${cat.name || cat.name_ar}`;\n      document.getElementById('categoryModal').classList.remove('hidden');\n    }\n\n    function closeCategoryModal() {\n      document.getElementById('categoryModal').classList.add('hidden');\n    }\n\n    async function handleCategorySubmit(e) {\n      e.preventDefault();\n      const editId = document.getElementById('catEditId').value;\n      const payload = {\n        name_ar: document.getElementById('catName').value.trim(),\n        slug: document.getElementById('catSlug').value.trim(),\n        description: document.getElementById('catDescription').value.trim(),\n        image_url: document.getElementById('catImageUrl').value.trim(),\n        sort_order: Number(document.getElementById('catSortOrder').value),\n        is_featured: document.getElementById('catIsFeatured').checked,\n      };\n\n      try {\n        const url = editId ? `${API_BASE}/categories/${editId}` : `${API_BASE}/categories`;\n        const method = editId ? 'PUT' : 'POST';\n        const res = await fetch(url, {\n          method,\n          headers: getHeaders(),\n          body: JSON.stringify(payload),\n        });\n\n        if (res.ok) {\n          showToast(editId ? '\u062A\u0645 \u062A\u062D\u062F\u064A\u062B \u0627\u0644\u0642\u0633\u0645 \u0628\u0646\u062C\u0627\u062D' : '\u062A\u0645\u062A \u0625\u0636\u0627\u0641\u0629 \u0627\u0644\u0642\u0633\u0645 \u0628\u0646\u062C\u0627\u062D');\n          closeCategoryModal();\n          loadCategories();\n        } else {\n          showToast('\u0641\u0634\u0644 \u062D\u0641\u0638 \u0627\u0644\u0642\u0633\u0645', 'error');\n        }\n      } catch (e) {\n        showToast('\u062D\u062F\u062B \u062E\u0637\u0623 \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u062D\u0641\u0638', 'error');\n      }\n    }\n\n    function confirmDeleteCategory(id, name) {\n      openDeleteModal(\n        `\u062D\u0630\u0641 \u0642\u0633\u0645: ${name}`,\n        `\u0647\u0644 \u0623\u0646\u062A \u0645\u062A\u0623\u0643\u062F \u0645\u0646 \u0631\u063A\u0628\u062A\u0643 \u0641\u064A \u062D\u0630\u0641 \u0642\u0633\u0645 \"${name}\"\u061F \u0642\u062F \u064A\u0624\u062B\u0631 \u0630\u0644\u0643 \u0639\u0644\u0649 \u0627\u0644\u0645\u0646\u062A\u062C\u0627\u062A \u0627\u0644\u0645\u0631\u062A\u0628\u0637\u0629 \u0628\u0647.`,\n        async () => {\n          try {\n            const res = await fetch(`${API_BASE}/categories/${id}`, {\n              method: 'DELETE',\n              headers: getHeaders(),\n            });\n            if (res.ok) {\n              showToast(`\u062A\u0645 \u062D\u0630\u0641 \u0642\u0633\u0645 \"${name}\" \u0628\u0646\u062C\u0627\u062D`);\n              loadCategories();\n            } else {\n              showToast('\u0641\u0634\u0644 \u062D\u0630\u0641 \u0627\u0644\u0642\u0633\u0645', 'error');\n            }\n          } catch (e) {\n            showToast('\u062D\u062F\u062B \u062E\u0637\u0623 \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u062D\u0630\u0641', 'error');\n          }\n        }\n      );\n    }\n\n    // \u2500\u2500 4. ORDERS \u2500\u2500\n    async function loadOrders(status = '') {\n      try {\n        let url = `${API_BASE}/orders`;\n        if (status && status !== 'all') url += `?status=${status}`;\n        const res = await fetch(url, { headers: getHeaders() });\n        if (!res.ok) return;\n        const data = await res.json();\n        ordersData = data.orders || [];\n        renderOrdersTable(ordersData);\n\n        // Synchronize accurate pending orders badge directly from live fetched orders\n        const pendingCount = ordersData.filter(o => o.status === 'pending').length;\n        const b = document.getElementById('badge-pending-orders');\n        if (b) {\n          b.textContent = pendingCount;\n          if (pendingCount > 0) b.classList.remove('hidden');\n          else b.classList.add('hidden');\n        }\n      } catch (e) {\n        console.warn('Orders error:', e);\n      }\n    }\n\n    function renderOrdersTable(list) {\n      const tbody = document.getElementById('orders-table-tbody');\n      tbody.innerHTML = '';\n      if (list.length === 0) {\n        tbody.innerHTML = `<tr><td colspan=\"8\" class=\"text-center py-8 text-slate-400\">\u0644\u0627 \u062A\u0648\u062C\u062F \u0637\u0644\u0628\u0627\u062A \u062A\u0637\u0627\u0628\u0642 \u0627\u0644\u0641\u0644\u062A\u0631</td></tr>`;\n        return;\n      }\n\n      list.forEach(o => {\n        const tr = document.createElement('tr');\n        tr.className = 'hover:bg-slate-50/70 transition-colors';\n        const itemCount = o.items ? o.items.length : 0;\n        tr.innerHTML = `\n          <td class=\"p-3 font-bold text-brand-700\">${o.orderNumber || o.order_number}</td>\n          <td class=\"p-3\">\n            <div class=\"font-bold text-slate-800\">${o.customer?.firstName} ${o.customer?.lastName || ''}</div>\n            <a href=\"https://wa.me/2${o.customer?.phone}\" target=\"_blank\" class=\"text-[11px] text-emerald-600 hover:underline flex items-center gap-1 font-mono\">\n              <i class=\"fa-brands fa-whatsapp\"></i> ${o.customer?.phone}\n            </a>\n          </td>\n          <td class=\"p-3\">\n            <div class=\"font-medium\">${o.address?.governorate} - ${o.address?.city}</div>\n            <div class=\"text-[10px] text-slate-400 truncate max-w-[150px]\">${o.address?.street}</div>\n          </td>\n          <td class=\"p-3\"><span class=\"bg-slate-100 text-slate-700 px-2 py-0.5 rounded-lg text-[11px] font-semibold\">${itemCount} \u0639\u0646\u0627\u0635\u0631</span></td>\n          <td class=\"p-3 font-bold text-slate-900\">${o.total} \u062C.\u0645</td>\n          <td class=\"p-3 text-[11px]\">${o.paymentMethod === 'cod' ? '\u062F\u0641\u0639 \u0639\u0646\u062F \u0627\u0644\u0627\u0633\u062A\u0644\u0627\u0645' : o.paymentMethod}</td>\n          <td class=\"p-3\">\n            <select onchange=\"updateOrderStatus('${o.id}', this.value)\" class=\"text-[11px] bg-slate-50 border border-slate-200 rounded-lg p-1 font-semibold focus:outline-none\">\n              <option value=\"pending\" ${o.status === 'pending' ? 'selected' : ''}>\u0645\u0639\u0644\u0642</option>\n              <option value=\"confirmed\" ${o.status === 'confirmed' ? 'selected' : ''}>\u0645\u0624\u0643\u062F</option>\n              <option value=\"processing\" ${o.status === 'processing' ? 'selected' : ''}>\u0642\u064A\u062F \u0627\u0644\u062A\u062C\u0647\u064A\u0632</option>\n              <option value=\"shipped\" ${o.status === 'shipped' ? 'selected' : ''}>\u062A\u0645 \u0627\u0644\u0634\u062D\u0646</option>\n              <option value=\"delivered\" ${o.status === 'delivered' ? 'selected' : ''}>\u062A\u0645 \u0627\u0644\u062A\u0633\u0644\u064A\u0645</option>\n              <option value=\"cancelled\" ${o.status === 'cancelled' ? 'selected' : ''}>\u0645\u0644\u063A\u064A</option>\n            </select>\n          </td>\n          <td class=\"p-3 text-center\">\n            <div class=\"flex items-center justify-center gap-2\">\n              <button onclick=\"viewOrderDetails('${o.id}')\" class=\"p-1.5 text-brand-600 hover:bg-brand-50 rounded-lg transition-colors\" title=\"\u062A\u0641\u0627\u0635\u064A\u0644 \u0627\u0644\u0637\u0644\u0628 \u0648\u0627\u0644\u0641\u0627\u062A\u0648\u0631\u0629\"><i class=\"fa-solid fa-eye\"></i></button>\n              <button onclick=\"confirmDeleteOrder('${o.id}', '${o.orderNumber || o.order_number}')\" class=\"p-1.5 text-slate-400 hover:text-rose-600 rounded-lg transition-colors\" title=\"\u062D\u0630\u0641 \u0627\u0644\u0637\u0644\u0628\"><i class=\"fa-solid fa-trash-can\"></i></button>\n            </div>\n          </td>\n        `;\n        tbody.appendChild(tr);\n      });\n    }\n\n    function filterOrders(status) {\n      document.querySelectorAll('[id^=\"btn-order-filter-\"]').forEach(btn => {\n        btn.className = 'px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-100 hover:bg-slate-200 text-slate-700';\n      });\n      document.getElementById(`btn-order-filter-${status}`).className = 'px-3 py-1.5 rounded-lg text-xs font-bold bg-brand-600 text-white';\n      loadOrders(status);\n    }\n\n    function handleOrderSearch(query) {\n      const q = query.toLowerCase().trim();\n      if (!q) { renderOrdersTable(ordersData); return; }\n      const filtered = ordersData.filter(o => \n        (o.orderNumber && o.orderNumber.toLowerCase().includes(q)) ||\n        (o.customer?.phone && o.customer.phone.includes(q)) ||\n        (o.customer?.firstName && `${o.customer.firstName} ${o.customer.lastName}`.toLowerCase().includes(q))\n      );\n      renderOrdersTable(filtered);\n    }\n\n    async function updateOrderStatus(orderId, newStatus) {\n      try {\n        const res = await fetch(`${API_BASE}/orders/${orderId}/status`, {\n          method: 'PATCH',\n          headers: getHeaders(),\n          body: JSON.stringify({ status: newStatus }),\n        });\n        if (res.ok) {\n          showToast(`\u062A\u0645 \u062A\u063A\u064A\u064A\u0631 \u062D\u0627\u0644\u0629 \u0627\u0644\u0637\u0644\u0628 \u0625\u0644\u0649 \"${newStatus}\"`);\n        } else {\n          showToast('\u0641\u0634\u0644 \u062A\u062D\u062F\u064A\u062B \u0627\u0644\u062D\u0627\u0644\u0629', 'error');\n        }\n      } catch (e) {\n        showToast('\u062D\u062F\u062B \u062E\u0637\u0623 \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u062A\u062D\u062F\u064A\u062B', 'error');\n      }\n    }\n\n    function viewOrderDetails(orderId) {\n      currentViewingOrderId = orderId;\n      const order = ordersData.find(o => o.id === orderId);\n      if (!order) return;\n\n      document.getElementById('modalOrderNumber').textContent = `\u0637\u0644\u0628 \u0631\u0642\u0645: ${order.orderNumber}`;\n      document.getElementById('modalOrderDate').textContent = `\u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0625\u0646\u0634\u0627\u0621: ${new Date(order.createdAt).toLocaleString('ar-EG')}`;\n\n      const content = document.getElementById('modalOrderContent');\n      content.innerHTML = `\n        <div class=\"grid grid-cols-2 gap-4 bg-slate-50 p-4 rounded-xl border border-slate-100\">\n          <div>\n            <span class=\"text-slate-400 block text-[10px]\">\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0639\u0645\u064A\u0644:</span>\n            <span class=\"font-bold text-slate-900\">${order.customer?.firstName} ${order.customer?.lastName}</span>\n            <div class=\"text-slate-600 font-mono\">${order.customer?.phone}</div>\n          </div>\n          <div>\n            <span class=\"text-slate-400 block text-[10px]\">\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0634\u062D\u0646:</span>\n            <span class=\"font-medium text-slate-800\">${order.address?.governorate} - ${order.address?.city}</span>\n            <div class=\"text-slate-600\">${order.address?.street} ${order.address?.apartment ? ' - ' + order.address.apartment : ''}</div>\n          </div>\n        </div>\n\n        <div class=\"space-y-2\">\n          <div class=\"font-bold text-slate-800\">\u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629:</div>\n          <div class=\"divide-y divide-slate-100 border border-slate-100 rounded-xl overflow-hidden\">\n            ${(order.items || []).map(item => `\n              <div class=\"p-3 bg-white flex items-center justify-between gap-3\">\n                <div class=\"flex items-center gap-3\">\n                  ${item.image ? `<img src=\"${item.image}\" class=\"w-12 h-12 rounded-lg object-cover\" />` : ''}\n                  <div>\n                    <div class=\"font-bold text-slate-900\">${item.name}</div>\n                    <div class=\"text-[11px] text-slate-500\">\u0627\u0644\u0643\u0645\u064A\u0629: ${item.quantity} \u00D7 ${item.price} \u062C.\u0645</div>\n                    ${item.selectedVariants ? `\n                      <div class=\"text-[10px] text-brand-600 mt-1\">\n                        ${Object.entries(item.selectedVariants).map(([k, v]) => `${k}: <b>${v}</b>`).join(' | ')}\n                      </div>\n                    ` : ''}\n                  </div>\n                </div>\n                <div class=\"text-left font-bold text-slate-900\">${item.price * item.quantity} \u062C.\u0645</div>\n              </div>\n            `).join('')}\n          </div>\n        </div>\n\n        <div class=\"bg-brand-50/50 p-3 rounded-xl space-y-1 text-slate-700\">\n          <div class=\"flex justify-between\"><span>\u0627\u0644\u0645\u062C\u0645\u0648\u0639 \u0627\u0644\u0641\u0631\u0639\u064A:</span><span>${order.subtotal} \u062C.\u0645</span></div>\n          <div class=\"flex justify-between\"><span>\u0645\u0635\u0627\u0631\u064A\u0641 \u0627\u0644\u0634\u062D\u0646:</span><span>${order.shippingCost} \u062C.\u0645</span></div>\n          ${order.discount ? `<div class=\"flex justify-between text-emerald-600\"><span>\u0627\u0644\u062E\u0635\u0645:</span><span>-${order.discount} \u062C.\u0645</span></div>` : ''}\n          <div class=\"flex justify-between font-black text-sm text-slate-900 pt-1 border-t border-brand-100\">\n            <span>\u0627\u0644\u0625\u062C\u0645\u0627\u0644\u064A \u0627\u0644\u0646\u0647\u0627\u0626\u064A:</span>\n            <span>${order.total} \u062C.\u0645</span>\n          </div>\n        </div>\n      `;\n\n      document.getElementById('orderModal').classList.remove('hidden');\n    }\n\n    function closeOrderModal() {\n      document.getElementById('orderModal').classList.add('hidden');\n    }\n\n    function confirmDeleteOrder(id, orderNumber) {\n      openDeleteModal(\n        `\u062D\u0630\u0641 \u0627\u0644\u0637\u0644\u0628: ${orderNumber}`,\n        `\u0647\u0644 \u0623\u0646\u062A \u0645\u062A\u0623\u0643\u062F \u0645\u0646 \u0631\u063A\u0628\u062A\u0643 \u0641\u064A \u062D\u0630\u0641 \u0627\u0644\u0637\u0644\u0628 \"${orderNumber}\" \u0646\u0647\u0627\u0626\u064A\u0627\u064B \u0645\u0646 \u0642\u0627\u0639\u062F\u0629 \u0628\u064A\u0627\u0646\u0627\u062A Supabase\u061F`,\n        async () => {\n          try {\n            const res = await fetch(`${API_BASE}/orders/${id}`, {\n              method: 'DELETE',\n              headers: getHeaders(),\n            });\n            if (res.ok) {\n              showToast(`\u062A\u0645 \u062D\u0630\u0641 \u0627\u0644\u0637\u0644\u0628 \"${orderNumber}\" \u0628\u0646\u062C\u0627\u062D`);\n              loadOrders();\n            } else {\n              showToast('\u0641\u0634\u0644 \u062D\u0630\u0641 \u0627\u0644\u0637\u0644\u0628', 'error');\n            }\n          } catch (e) {\n            showToast('\u062D\u062F\u062B \u062E\u0637\u0623 \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u062D\u0630\u0641', 'error');\n          }\n        }\n      );\n    }\n\n    function deleteCurrentOrder() {\n      if (currentViewingOrderId) {\n        closeOrderModal();\n        confirmDeleteOrder(currentViewingOrderId, '\u0627\u0644\u0645\u062D\u062F\u062F');\n      }\n    }\n\n    // \u2500\u2500 5. CUSTOM CHAIRS \u2500\u2500\n    async function loadChairRequests() {\n      try {\n        const res = await fetch(`${API_BASE}/chair-custom`, { headers: getHeaders() });\n        if (!res.ok) return;\n        const requests = await res.json();\n\n        // Synchronize accurate new chairs badge directly from live fetched requests\n        const newChairsCount = requests.filter(r => r.status === 'new').length;\n        const b = document.getElementById('badge-new-chairs');\n        if (b) {\n          b.textContent = newChairsCount;\n          if (newChairsCount > 0) b.classList.remove('hidden');\n          else b.classList.add('hidden');\n        }\n\n        const grid = document.getElementById('chair-requests-grid');\n        grid.innerHTML = '';\n        if (requests.length === 0) {\n          grid.innerHTML = `<div class=\"col-span-3 text-center py-12 text-slate-400 bg-white rounded-2xl border border-slate-200\">\u0644\u0627 \u062A\u0648\u062C\u062F \u0637\u0644\u0628\u0627\u062A \u0643\u0631\u0627\u0633\u064A \u0639\u0645\u0648\u0644\u0629 \u062C\u062F\u064A\u062F\u0629 \u062D\u0627\u0644\u064A\u0627\u064B</div>`;\n          return;\n        }\n\n        requests.forEach(req => {\n          const card = document.createElement('div');\n          card.className = 'bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm flex flex-col justify-between hover:shadow-md transition-shadow';\n          card.innerHTML = `\n            <div>\n              <div class=\"relative h-48 bg-slate-100 group cursor-pointer overflow-hidden\" onclick=\"openImageModal('${req.uploaded_photo_url}', '\u0635\u0648\u0631\u0629 \u0643\u0631\u0633\u064A \u0627\u0644\u0639\u0645\u064A\u0644: ${req.customer_name}')\">\n                <img src=\"${req.uploaded_photo_url}\" alt=\"\u0635\u0648\u0631\u0629 \u0627\u0644\u0643\u0631\u0633\u064A\" class=\"w-full h-full object-cover group-hover:scale-105 transition-transform duration-300\" />\n                <div class=\"absolute inset-0 bg-black/30 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center text-white gap-2 font-bold text-xs\">\n                  <i class=\"fa-solid fa-magnifying-glass-plus text-lg\"></i>\n                  \u0645\u0639\u0627\u064A\u0646\u0629 \u0648\u062A\u0643\u0628\u064A\u0631 \u0627\u0644\u0635\u0648\u0631\u0629\n                </div>\n                <div class=\"absolute top-3 right-3\">${renderStatusBadge(req.status)}</div>\n              </div>\n\n              <div class=\"p-4 space-y-3\">\n                <div class=\"flex items-center justify-between\">\n                  <h3 class=\"font-bold text-sm text-slate-900\">${req.customer_name}</h3>\n                  <span class=\"text-xs font-semibold text-brand-700\">+${req.custom_extra_fee} \u062C.\u0645 (\u0639\u0645\u0648\u0644\u0629)</span>\n                </div>\n                <div class=\"text-xs text-slate-500 font-mono\">${req.customer_phone}</div>\n\n                <div class=\"bg-slate-50 p-2.5 rounded-xl border border-slate-100 space-y-1 text-xs\">\n                  <div class=\"flex justify-between\"><span class=\"text-slate-400\">\u0627\u0644\u0644\u0648\u0646 \u0627\u0644\u0645\u062E\u062A\u0627\u0631:</span><span class=\"font-bold text-slate-800\">${req.fabric_color}</span></div>\n                  <div class=\"flex justify-between\"><span class=\"text-slate-400\">\u0627\u0644\u0646\u0642\u0634\u0629:</span><span class=\"font-bold text-slate-800\">${req.pattern_type}</span></div>\n                  <div class=\"flex justify-between\"><span class=\"text-slate-400\">\u0639\u062F\u062F \u0627\u0644\u0643\u0631\u0627\u0633\u064A:</span><span class=\"font-bold text-slate-800\">${req.chairs_count} \u0643\u0631\u0627\u0633\u064A</span></div>\n                </div>\n\n                ${req.admin_notes ? `<div class=\"text-[11px] text-amber-700 bg-amber-50 p-2 rounded-lg border border-amber-100 font-medium\">\u0645\u0644\u0627\u062D\u0638\u0627\u062A: ${req.admin_notes}</div>` : ''}\n              </div>\n            </div>\n\n            <div class=\"p-4 pt-0 border-t border-slate-100 space-y-2\">\n              <a href=\"${req.whatsapp_link}\" target=\"_blank\" class=\"w-full py-2 bg-emerald-600 hover:bg-emerald-700 text-white font-bold rounded-xl text-xs flex items-center justify-center gap-2 shadow-sm transition-colors\">\n                <i class=\"fa-brands fa-whatsapp text-sm\"></i>\n                \u0628\u062F\u0621 \u0645\u062D\u0627\u062F\u062B\u0629 \u0648\u0627\u062A\u0633\u0627\u0628 \u0645\u0639 \u0627\u0644\u0639\u0645\u064A\u0644\n              </a>\n              <div class=\"flex items-center justify-between text-[11px] pt-1\">\n                <span class=\"text-slate-400\">\u062A\u062D\u062F\u064A\u062B \u0627\u0644\u062D\u0627\u0644\u0629:</span>\n                <select onchange=\"updateChairStatus('${req.id}', this.value)\" class=\"bg-slate-50 border border-slate-200 rounded-lg px-2 py-1 font-semibold text-xs focus:outline-none\">\n                  <option value=\"new\" ${req.status === 'new' ? 'selected' : ''}>\u062C\u062F\u064A\u062F</option>\n                  <option value=\"contacted\" ${req.status === 'contacted' ? 'selected' : ''}>\u062A\u0645 \u0627\u0644\u062A\u0648\u0627\u0635\u0644</option>\n                  <option value=\"in_tailoring\" ${req.status === 'in_tailoring' ? 'selected' : ''}>\u062C\u0627\u0631\u064A \u0627\u0644\u062A\u0641\u0635\u064A\u0644</option>\n                  <option value=\"completed\" ${req.status === 'completed' ? 'selected' : ''}>\u0645\u0643\u062A\u0645\u0644</option>\n                  <option value=\"cancelled\" ${req.status === 'cancelled' ? 'selected' : ''}>\u0645\u0644\u063A\u064A</option>\n                </select>\n              </div>\n            </div>\n          `;\n          grid.appendChild(card);\n        });\n      } catch (e) {\n        console.warn('Chair requests error:', e);\n      }\n    }\n\n    async function updateChairStatus(reqId, status) {\n      try {\n        const res = await fetch(`${API_BASE}/chair-custom/${reqId}/status`, {\n          method: 'PATCH',\n          headers: getHeaders(),\n          body: JSON.stringify({ status }),\n        });\n        if (res.ok) {\n          showToast('\u062A\u0645 \u062A\u062D\u062F\u064A\u062B \u062D\u0627\u0644\u0629 \u0637\u0644\u0628 \u0627\u0644\u062A\u0641\u0635\u064A\u0644 \u0641\u064A Supabase');\n        } else {\n          showToast('\u0641\u0634\u0644 \u0627\u0644\u062A\u062D\u062F\u064A\u062B', 'error');\n        }\n      } catch (e) {\n        showToast('\u062D\u062F\u062B \u062E\u0637\u0623', 'error');\n      }\n    }\n\n    function openImageModal(url, caption) {\n      document.getElementById('modalPreviewImage').src = url;\n      document.getElementById('modalImageCaption').textContent = caption;\n      document.getElementById('imageModal').classList.remove('hidden');\n    }\n\n    function closeImageModal() {\n      document.getElementById('imageModal').classList.add('hidden');\n    }\n\n    // \u2500\u2500 6. CLIENTS / CUSTOMERS CRM \u2500\u2500\n    async function loadCustomers() {\n      try {\n        const res = await fetch(`${API_BASE}/customers`, { headers: getHeaders() });\n        if (!res.ok) return;\n        customersData = await res.json();\n        document.getElementById('badge-clients-count').textContent = customersData.length;\n\n        const tbody = document.getElementById('customers-table-tbody');\n        tbody.innerHTML = '';\n        if (customersData.length === 0) {\n          tbody.innerHTML = `<tr><td colspan=\"6\" class=\"text-center py-8 text-slate-400\">\u0644\u0627 \u064A\u0648\u062C\u062F \u0639\u0645\u0644\u0627\u0621 \u0645\u0633\u062C\u0644\u064A\u0646 \u0628\u0639\u062F. \u0627\u0636\u063A\u0637 \"\u0625\u0636\u0627\u0641\u0629 \u0639\u0645\u064A\u0644 \u062C\u062F\u064A\u062F\" \u0644\u0625\u0636\u0627\u0641\u0629 \u0623\u0648\u0644 \u0639\u0645\u064A\u0644!</td></tr>`;\n          return;\n        }\n\n        customersData.forEach(c => {\n          const tr = document.createElement('tr');\n          tr.className = 'hover:bg-slate-50/70 transition-colors';\n          tr.innerHTML = `\n            <td class=\"p-3\">\n              <div class=\"font-bold text-slate-900\">${c.name}</div>\n              <div class=\"text-[10px] text-slate-400 font-mono\">${c.email || ''}</div>\n            </td>\n            <td class=\"p-3 font-mono font-medium\">${c.phone}</td>\n            <td class=\"p-3 text-slate-600\">${c.governorate || '-'} ${c.city ? ' - ' + c.city : ''}</td>\n            <td class=\"p-3 font-semibold\">${c.totalOrders} \u0637\u0644\u0628\u0627\u062A</td>\n            <td class=\"p-3 font-bold text-emerald-600\">${(c.totalSpend || 0).toLocaleString()} \u062C.\u0645</td>\n            <td class=\"p-3 text-center\">\n              <div class=\"flex items-center justify-center gap-2\">\n                <a href=\"https://wa.me/2${c.phone}\" target=\"_blank\" class=\"px-2 py-1 bg-emerald-50 text-emerald-700 hover:bg-emerald-100 font-bold rounded-lg text-xs inline-flex items-center gap-1\" title=\"\u0648\u0627\u062A\u0633\u0627\u0628 \u0641\u0648\u0631\u064A\">\n                  <i class=\"fa-brands fa-whatsapp text-sm\"></i>\n                  \u0648\u0627\u062A\u0633\u0627\u0628\n                </a>\n                <button onclick=\"editCustomer('${c.id}')\" class=\"p-1.5 text-slate-400 hover:text-brand-600 rounded\" title=\"\u062A\u0639\u062F\u064A\u0644\"><i class=\"fa-solid fa-pen-to-square\"></i></button>\n                <button onclick=\"confirmDeleteCustomer('${c.id}', '${c.name}')\" class=\"p-1.5 text-slate-400 hover:text-rose-600 rounded\" title=\"\u062D\u0630\u0641\"><i class=\"fa-solid fa-trash-can\"></i></button>\n              </div>\n            </td>\n          `;\n          tbody.appendChild(tr);\n        });\n      } catch (e) {\n        console.warn('Customers error:', e);\n      }\n    }\n\n    function openCustomerModal() {\n      document.getElementById('customerForm').reset();\n      document.getElementById('custEditId').value = '';\n      document.getElementById('customerModalTitle').textContent = '\u0625\u0636\u0627\u0641\u0629 \u0639\u0645\u064A\u0644 \u062C\u062F\u064A\u062F';\n      document.getElementById('customerModal').classList.remove('hidden');\n    }\n\n    function editCustomer(id) {\n      const cust = customersData.find(c => c.id === id);\n      if (!cust) return;\n\n      document.getElementById('custEditId').value = cust.id;\n      document.getElementById('custName').value = cust.name;\n      document.getElementById('custPhone').value = cust.phone;\n      document.getElementById('custEmail').value = cust.email || '';\n      document.getElementById('custGovernorate').value = cust.governorate || '';\n      document.getElementById('custCity').value = cust.city || '';\n      document.getElementById('custAddress').value = cust.street_address || '';\n      document.getElementById('custNotes').value = cust.notes || '';\n\n      document.getElementById('customerModalTitle').textContent = `\u062A\u0639\u062F\u064A\u0644 \u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0639\u0645\u064A\u0644: ${cust.name}`;\n      document.getElementById('customerModal').classList.remove('hidden');\n    }\n\n    function closeCustomerModal() {\n      document.getElementById('customerModal').classList.add('hidden');\n    }\n\n    async function handleCustomerSubmit(e) {\n      e.preventDefault();\n      const editId = document.getElementById('custEditId').value;\n      const payload = {\n        name: document.getElementById('custName').value.trim(),\n        phone: document.getElementById('custPhone').value.trim(),\n        email: document.getElementById('custEmail').value.trim() || undefined,\n        governorate: document.getElementById('custGovernorate').value.trim() || undefined,\n        city: document.getElementById('custCity').value.trim() || undefined,\n        street_address: document.getElementById('custAddress').value.trim() || undefined,\n        notes: document.getElementById('custNotes').value.trim() || undefined,\n      };\n\n      try {\n        const url = editId ? `${API_BASE}/customers/${editId}` : `${API_BASE}/customers`;\n        const method = editId ? 'PUT' : 'POST';\n        const res = await fetch(url, {\n          method,\n          headers: getHeaders(),\n          body: JSON.stringify(payload),\n        });\n\n        if (res.ok) {\n          showToast(editId ? '\u062A\u0645 \u062A\u062D\u062F\u064A\u062B \u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0639\u0645\u064A\u0644 \u0628\u0646\u062C\u0627\u062D' : '\u062A\u0645\u062A \u0625\u0636\u0627\u0641\u0629 \u0627\u0644\u0639\u0645\u064A\u0644 \u0628\u0646\u062C\u0627\u062D');\n          closeCustomerModal();\n          loadCustomers();\n        } else {\n          const err = await res.json();\n          showToast(`\u062E\u0637\u0623: ${err.message || '\u0641\u0634\u0644\u062A \u0627\u0644\u0639\u0645\u0644\u064A\u0629'}`, 'error');\n        }\n      } catch (e) {\n        showToast('\u062D\u062F\u062B \u062E\u0637\u0623 \u0623\u062B\u0646\u0627\u0621 \u062D\u0641\u0638 \u0627\u0644\u0639\u0645\u064A\u0644', 'error');\n      }\n    }\n\n    function confirmDeleteCustomer(id, name) {\n      openDeleteModal(\n        `\u062D\u0630\u0641 \u0627\u0644\u0639\u0645\u064A\u0644: ${name}`,\n        `\u0647\u0644 \u0623\u0646\u062A \u0645\u062A\u0623\u0643\u062F \u0645\u0646 \u0631\u063A\u0628\u062A\u0643 \u0641\u064A \u062D\u0630\u0641 \u0627\u0644\u0639\u0645\u064A\u0644 \"${name}\" \u0645\u0646 \u0642\u0627\u0639\u062F\u0629 \u0628\u064A\u0627\u0646\u0627\u062A Supabase\u061F`,\n        async () => {\n          try {\n            const res = await fetch(`${API_BASE}/customers/${id}`, {\n              method: 'DELETE',\n              headers: getHeaders(),\n            });\n            if (res.ok) {\n              showToast(`\u062A\u0645 \u062D\u0630\u0641 \u0627\u0644\u0639\u0645\u064A\u0644 \"${name}\" \u0628\u0646\u062C\u0627\u062D`);\n              loadCustomers();\n            } else {\n              showToast('\u0641\u0634\u0644 \u062D\u0630\u0641 \u0627\u0644\u0639\u0645\u064A\u0644', 'error');\n            }\n          } catch (e) {\n            showToast('\u062D\u062F\u062B \u062E\u0637\u0623 \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u062D\u0630\u0641', 'error');\n          }\n        }\n      );\n    }\n\n    // \u2500\u2500 7. EXPENSES \u2500\u2500\n    async function loadExpenses() {\n      try {\n        const res = await fetch(`${API_BASE}/expenses`, { headers: getHeaders() });\n        if (!res.ok) return;\n        expensesData = await res.json();\n\n        const tbody = document.getElementById('expenses-table-tbody');\n        tbody.innerHTML = '';\n        if (expensesData.length === 0) {\n          tbody.innerHTML = `<tr><td colspan=\"6\" class=\"text-center py-8 text-slate-400\">\u0644\u0627 \u062A\u0648\u062C\u062F \u0628\u0646\u0648\u062F \u0645\u0635\u0631\u0648\u0641\u0627\u062A \u0645\u0633\u062C\u0644\u0629 \u0628\u0639\u062F</td></tr>`;\n          return;\n        }\n\n        expensesData.forEach(exp => {\n          const tr = document.createElement('tr');\n          tr.className = 'hover:bg-slate-50/70 transition-colors';\n          tr.innerHTML = `\n            <td class=\"p-3 font-bold text-slate-900\">${exp.title}</td>\n            <td class=\"p-3\"><span class=\"px-2 py-0.5 rounded-lg text-[10px] font-bold bg-slate-100 text-slate-700\">${exp.category.replace('_', ' ')}</span></td>\n            <td class=\"p-3 font-bold text-rose-600 font-mono\">${(exp.amount || 0).toLocaleString()} \u062C.\u0645</td>\n            <td class=\"p-3 text-slate-400 font-mono\">${new Date(exp.date).toLocaleDateString('ar-EG')}</td>\n            <td class=\"p-3 text-slate-500\">${exp.notes || '-'}</td>\n            <td class=\"p-3 text-center\">\n              <button onclick=\"confirmDeleteExpense('${exp.id}', '${exp.title}')\" class=\"p-1.5 text-slate-400 hover:text-rose-600 rounded\" title=\"\u062D\u0630\u0641\"><i class=\"fa-solid fa-trash-can\"></i></button>\n            </td>\n          `;\n          tbody.appendChild(tr);\n        });\n      } catch (e) {\n        console.warn('Expenses error:', e);\n      }\n    }\n\n    function openExpenseModal() {\n      document.getElementById('expenseForm').reset();\n      document.getElementById('expenseModal').classList.remove('hidden');\n    }\n\n    function closeExpenseModal() {\n      document.getElementById('expenseModal').classList.add('hidden');\n    }\n\n    async function handleExpenseSubmit(e) {\n      e.preventDefault();\n      const payload = {\n        title: document.getElementById('expTitle').value.trim(),\n        amount: Number(document.getElementById('expAmount').value),\n        category: document.getElementById('expCategory').value,\n        notes: document.getElementById('expNotes').value.trim() || undefined,\n      };\n\n      try {\n        const res = await fetch(`${API_BASE}/expenses`, {\n          method: 'POST',\n          headers: getHeaders(),\n          body: JSON.stringify(payload),\n        });\n\n        if (res.ok) {\n          showToast('\u062A\u0645 \u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u0645\u0635\u0631\u0648\u0641 \u0628\u0646\u062C\u0627\u062D');\n          closeExpenseModal();\n          loadExpenses();\n          loadOverview(); // update financials\n        } else {\n          showToast('\u0641\u0634\u0644 \u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u0645\u0635\u0631\u0648\u0641', 'error');\n        }\n      } catch (e) {\n        showToast('\u062D\u062F\u062B \u062E\u0637\u0623 \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u062D\u0641\u0638', 'error');\n      }\n    }\n\n    function confirmDeleteExpense(id, title) {\n      openDeleteModal(\n        `\u062D\u0630\u0641 \u0627\u0644\u0645\u0635\u0631\u0648\u0641: ${title}`,\n        `\u0647\u0644 \u0623\u0646\u062A \u0645\u062A\u0623\u0643\u062F \u0645\u0646 \u062D\u0630\u0641 \u0647\u0630\u0627 \u0627\u0644\u0645\u0635\u0631\u0648\u0641\u061F \u0633\u064A\u062A\u0645 \u0625\u0639\u0627\u062F\u0629 \u062D\u0633\u0627\u0628 \u0635\u0627\u0641\u064A \u0627\u0644\u0623\u0631\u0628\u0627\u062D \u062A\u0644\u0642\u0627\u0626\u064A\u0627\u064B.`,\n        async () => {\n          try {\n            const res = await fetch(`${API_BASE}/expenses/${id}`, {\n              method: 'DELETE',\n              headers: getHeaders(),\n            });\n            if (res.ok) {\n              showToast('\u062A\u0645 \u062D\u0630\u0641 \u0627\u0644\u0645\u0635\u0631\u0648\u0641 \u0628\u0646\u062C\u0627\u062D');\n              loadExpenses();\n              loadOverview();\n            } else {\n              showToast('\u0641\u0634\u0644 \u0627\u0644\u062D\u0630\u0641', 'error');\n            }\n          } catch (e) {\n            showToast('\u062D\u062F\u062B \u062E\u0637\u0623 \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u062D\u0630\u0641', 'error');\n          }\n        }\n      );\n    }\n\n    // \u2500\u2500 8. SHIPPING ZONES (With Clear Arabic Badges & Status) \u2500\u2500\n    async function loadShippingZones() {\n      try {\n        const res = await fetch(`${API_BASE}/shipping/zones`);\n        if (!res.ok) return;\n        const zones = await res.json();\n\n        const tbody = document.getElementById('shipping-table-tbody');\n        tbody.innerHTML = '';\n        zones.forEach(z => {\n          const tr = document.createElement('tr');\n          tr.className = 'hover:bg-slate-50/70 transition-colors';\n          tr.innerHTML = `\n            <td class=\"p-3 font-bold text-slate-900\">${z.governorate_name_ar}</td>\n            <td class=\"p-3\">\n              <input type=\"number\" id=\"fee-${z.id}\" value=\"${z.shipping_fee}\" class=\"w-20 text-xs bg-slate-50 border border-slate-200 rounded p-1 text-center font-bold\" />\n            </td>\n            <td class=\"p-3\">\n              <input type=\"text\" id=\"days-${z.id}\" value=\"${z.estimated_days}\" class=\"w-36 text-xs bg-slate-50 border border-slate-200 rounded p-1 font-medium\" />\n            </td>\n            <td class=\"p-3\">\n              <div class=\"flex items-center gap-3\">\n                <label class=\"inline-flex items-center cursor-pointer\">\n                  <input type=\"checkbox\" id=\"active-${z.id}\" onchange=\"toggleShippingBadge('${z.id}')\" ${z.is_active ? 'checked' : ''} class=\"sr-only peer\">\n                  <div class=\"w-9 h-5 bg-slate-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:right-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-emerald-600\"></div>\n                </label>\n                <span id=\"badge-shipping-${z.id}\">\n                  ${z.is_active \n                    ? `<span class=\"px-2.5 py-1 rounded-full text-[11px] font-bold bg-emerald-100 text-emerald-800 flex items-center gap-1.5\"><span class=\"w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse\"></span>\u0645\u062A\u0627\u062D \u0644\u0644\u062A\u0648\u0635\u064A\u0644</span>` \n                    : `<span class=\"px-2.5 py-1 rounded-full text-[11px] font-bold bg-slate-100 text-slate-500\">\u0627\u0644\u062A\u0648\u0635\u064A\u0644 \u0645\u062A\u0648\u0642\u0641</span>`}\n                </span>\n              </div>\n            </td>\n            <td class=\"p-3 text-center\">\n              <button onclick=\"saveZone('${z.id}', '${z.governorate_name_ar}')\" class=\"px-3 py-1 bg-brand-50 hover:bg-brand-100 text-brand-700 font-bold rounded-lg text-xs transition-colors\">\n                \u062D\u0641\u0638 \u0639\u0644\u0649 Supabase\n              </button>\n            </td>\n          `;\n          tbody.appendChild(tr);\n        });\n      } catch (e) {\n        console.warn('Shipping zones error:', e);\n      }\n    }\n\n    function toggleShippingBadge(id) {\n      const isChecked = document.getElementById(`active-${id}`).checked;\n      const badgeSpan = document.getElementById(`badge-shipping-${id}`);\n      if (isChecked) {\n        badgeSpan.innerHTML = `<span class=\"px-2.5 py-1 rounded-full text-[11px] font-bold bg-emerald-100 text-emerald-800 flex items-center gap-1.5\"><span class=\"w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse\"></span>\u0645\u062A\u0627\u062D \u0644\u0644\u062A\u0648\u0635\u064A\u0644</span>`;\n      } else {\n        badgeSpan.innerHTML = `<span class=\"px-2.5 py-1 rounded-full text-[11px] font-bold bg-slate-100 text-slate-500\">\u0627\u0644\u062A\u0648\u0635\u064A\u0644 \u0645\u062A\u0648\u0642\u0641</span>`;\n      }\n    }\n\n    async function saveZone(id, name) {\n      const fee = Number(document.getElementById(`fee-${id}`).value);\n      const days = document.getElementById(`days-${id}`).value;\n      const isActive = document.getElementById(`active-${id}`).checked;\n\n      try {\n        const res = await fetch(`${API_BASE}/shipping/zones/${id}`, {\n          method: 'PUT',\n          headers: getHeaders(),\n          body: JSON.stringify({ shipping_fee: fee, estimated_days: days, is_active: isActive }),\n        });\n        if (res.ok) {\n          showToast(`\u062A\u0645 \u062D\u0641\u0638 \u062A\u0639\u062F\u064A\u0644 \u0645\u062D\u0627\u0641\u0638\u0629 ${name} \u0639\u0644\u0649 Supabase`);\n        } else {\n          showToast('\u0641\u0634\u0644 \u0627\u0644\u062A\u0639\u062F\u064A\u0644', 'error');\n        }\n      } catch (e) {\n        showToast('\u062D\u062F\u062B \u062E\u0637\u0623 \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u062D\u0641\u0638', 'error');\n      }\n    }\n\n    // \u2500\u2500 9. STAFF & ROLES (Permissions Module) \u2500\u2500\n    async function loadStaffUsers() {\n      try {\n        const res = await fetch(`${API_BASE}/admin/users`, { headers: getHeaders() });\n        if (!res.ok) return;\n        staffData = await res.json();\n\n        // Update 4 Role Stat Cards\n        const total = staffData.length;\n        const admins = staffData.filter(u => u.role === 'ADMIN').length;\n        const managers = staffData.filter(u => u.role === 'MANAGER').length;\n        const support = staffData.filter(u => u.role === 'SUPPORT' || u.role === 'CUSTOM').length;\n\n        const statTotal = document.getElementById('stat-staff-total');\n        if (statTotal) statTotal.textContent = total;\n        const statAdmins = document.getElementById('stat-staff-admins');\n        if (statAdmins) statAdmins.textContent = admins;\n        const statManagers = document.getElementById('stat-staff-managers');\n        if (statManagers) statManagers.textContent = managers;\n        const statSupport = document.getElementById('stat-staff-support');\n        if (statSupport) statSupport.textContent = support;\n\n        const badgeStaff = document.getElementById('badge-staff-count');\n        if (badgeStaff) badgeStaff.textContent = total;\n\n        const tbody = document.getElementById('staff-table-tbody');\n        tbody.innerHTML = '';\n        if (staffData.length === 0) {\n          tbody.innerHTML = `<tr><td colspan=\"7\" class=\"text-center py-8 text-slate-400\">\u0644\u0627 \u064A\u0648\u062C\u062F \u0645\u0634\u0631\u0641\u064A\u0646 \u0645\u0633\u062C\u0644\u064A\u0646 \u0628\u0639\u062F. \u0627\u0636\u063A\u0637 \"\u0625\u0636\u0627\u0641\u0629 \u0645\u0634\u0631\u0641 \u0648\u0635\u0644\u0627\u062D\u064A\u0627\u062A\" \u0644\u0625\u0636\u0627\u0641\u0629 \u0645\u0634\u0631\u0641 \u062C\u062F\u064A\u062F!</td></tr>`;\n          return;\n        }\n\n        staffData.forEach(u => {\n          const tr = document.createElement('tr');\n          tr.className = 'hover:bg-slate-50/70 transition-colors';\n          const roleLabel = u.role === 'ADMIN' ? '\u0645\u062F\u064A\u0631 \u0639\u0627\u0645 (ADMIN)' : u.role === 'MANAGER' ? '\u0645\u0634\u0631\u0641 \u0639\u0645\u0644\u064A\u0627\u062A (MANAGER)' : u.role === 'SUPPORT' ? '\u062E\u062F\u0645\u0629 \u0639\u0645\u0644\u0627\u0621 (SUPPORT)' : '\u0645\u062E\u0635\u0635 (CUSTOM)';\n          const roleColor = u.role === 'ADMIN' ? 'bg-purple-100 text-purple-800' : u.role === 'MANAGER' ? 'bg-blue-100 text-blue-800' : u.role === 'SUPPORT' ? 'bg-teal-100 text-teal-800' : 'bg-amber-100 text-amber-800';\n\n          const userPerms = (u.permissions && u.permissions.length > 0) ? u.permissions : (ROLE_PERMISSIONS_TEMPLATE[u.role] || []);\n          let permsHtml = '';\n          if (u.role === 'ADMIN') {\n            permsHtml = `<span class=\"px-2 py-0.5 rounded-md text-[10px] font-bold bg-purple-50 text-purple-700 border border-purple-200\">\u0643\u0627\u0645\u0644 \u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0627\u062A (9 \u0623\u0642\u0633\u0627\u0645)</span>`;\n          } else {\n            permsHtml = `<div class=\"flex flex-wrap gap-1 max-w-xs\">` +\n              userPerms.map(p => `<span class=\"px-1.5 py-0.5 rounded text-[9px] font-semibold bg-slate-100 text-slate-700 border border-slate-200\">${MODULE_NAMES[p] || p}</span>`).join('') +\n              `</div>`;\n          }\n\n          tr.innerHTML = `\n            <td class=\"p-3\">\n              <div class=\"font-bold text-slate-900\">${u.full_name}</div>\n              <div class=\"text-[10px] text-slate-400 font-mono\">${u.id.slice(0, 8)}...</div>\n            </td>\n            <td class=\"p-3 font-mono text-slate-600\">${u.email}</td>\n            <td class=\"p-3\"><span class=\"px-2.5 py-1 rounded-full text-[10px] font-bold ${roleColor}\">${roleLabel}</span></td>\n            <td class=\"p-3\">${permsHtml}</td>\n            <td class=\"p-3\">${u.is_active ? '<span class=\"px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 text-emerald-800\">\u0646\u0634\u0637</span>' : '<span class=\"px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 text-slate-500\">\u0645\u0639\u0637\u0644</span>'}</td>\n            <td class=\"p-3 text-slate-400 font-mono\">${new Date(u.created_at).toLocaleDateString('ar-EG')}</td>\n            <td class=\"p-3 text-center\">\n              <div class=\"flex items-center justify-center gap-2\">\n                <button onclick=\"editStaff('${u.id}')\" class=\"p-1.5 text-slate-400 hover:text-brand-600 rounded transition-colors\" title=\"\u062A\u0639\u062F\u064A\u0644 \u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0627\u062A \u0648\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0645\u0634\u0631\u0641\"><i class=\"fa-solid fa-pen-to-square\"></i></button>\n                ${u.email !== 'admin@zahra-store.com' ? `\n                  <button onclick=\"confirmDeleteStaff('${u.id}', '${u.full_name}')\" class=\"p-1.5 text-slate-400 hover:text-rose-600 rounded transition-colors\" title=\"\u062D\u0630\u0641 \u0627\u0644\u0645\u0634\u0631\u0641\"><i class=\"fa-solid fa-trash-can\"></i></button>\n                ` : '<span class=\"text-[10px] text-slate-400 font-bold\">\u0627\u0644\u0645\u062F\u064A\u0631 \u0627\u0644\u0623\u0633\u0627\u0633\u064A</span>'}\n              </div>\n            </td>\n          `;\n          tbody.appendChild(tr);\n        });\n        loadPermissions();\n      } catch (e) {\n        console.warn('Staff error:', e);\n      }\n    }\n\n    // \u2500\u2500 10. PERMISSIONS REGISTRY MODULE \u2500\u2500\n    async function loadPermissions() {\n      try {\n        const res = await fetch(`${API_BASE}/permissions`, { headers: getHeaders() });\n        if (!res.ok) return;\n        systemPermissions = await res.json();\n\n        // Render in Registry Grid in #panel-staff\n        const grid = document.getElementById('permissions-registry-grid');\n        if (grid) {\n          grid.innerHTML = '';\n          systemPermissions.forEach(p => {\n            const card = document.createElement('div');\n            card.className = 'p-3.5 bg-slate-50 rounded-xl border border-slate-200 flex flex-col justify-between hover:border-brand-300 transition-colors';\n            card.innerHTML = `\n              <div>\n                <div class=\"flex items-center justify-between\">\n                  <div class=\"flex items-center gap-2\">\n                    <div class=\"w-7 h-7 rounded-lg bg-white border border-slate-200 flex items-center justify-center text-brand-600 text-xs\">\n                      <i class=\"fa-solid ${p.icon || 'fa-shield-halved'}\"></i>\n                    </div>\n                    <span class=\"font-bold text-slate-900 text-xs\">${p.name_ar}</span>\n                  </div>\n                  <span class=\"px-2 py-0.5 rounded-full text-[10px] font-mono font-bold bg-brand-50 text-brand-700\">${p.key}</span>\n                </div>\n                <p class=\"text-[11px] text-slate-500 mt-2 line-clamp-2\">${p.description || '\u0635\u0644\u0627\u062D\u064A\u0629 \u0648\u0635\u0648\u0644 \u062A\u0634\u063A\u064A\u0644\u064A\u0629'}</p>\n              </div>\n              <div class=\"mt-3 pt-2 border-t border-slate-200 flex items-center justify-between text-[10px]\">\n                <span class=\"text-slate-400 font-mono\">\u0627\u0644\u0648\u062D\u062F\u0629: ${p.module}</span>\n                <button onclick=\"confirmDeletePermission('${p.id}', '${p.name_ar}')\" class=\"p-1 text-slate-400 hover:text-rose-600 rounded transition-colors\" title=\"\u062D\u0630\u0641 \u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0629\">\n                  <i class=\"fa-solid fa-trash-can\"></i>\n                </button>\n              </div>\n            `;\n            grid.appendChild(card);\n          });\n        }\n\n        renderPermissionsChecklist();\n      } catch (e) {\n        console.warn('Permissions load error:', e);\n      }\n    }\n\n    function renderPermissionsChecklist(selectedKeys = []) {\n      const container = document.getElementById('permissionsChecklistGrid');\n      if (!container) return;\n      container.innerHTML = '';\n\n      const list = systemPermissions.length > 0 ? systemPermissions : ALL_MODULES_KEYS.map(k => ({\n        key: k,\n        name_ar: MODULE_NAMES[k] || k,\n        icon: 'fa-shield-halved'\n      }));\n\n      list.forEach(p => {\n        const isChecked = selectedKeys.length > 0 ? selectedKeys.includes(p.key) : true;\n        const label = document.createElement('label');\n        label.className = 'flex items-center gap-2 p-2 bg-white rounded-lg border border-slate-200 cursor-pointer hover:border-brand-300';\n        label.innerHTML = `\n          <input type=\"checkbox\" id=\"perm-${p.key}\" value=\"${p.key}\" onchange=\"updateSelectedPermsCount()\" ${isChecked ? 'checked' : ''} class=\"rounded text-brand-600 w-3.5 h-3.5\" />\n          <span class=\"flex items-center gap-1.5 truncate\">\n            <i class=\"fa-solid ${p.icon || 'fa-shield-halved'} text-[10px] text-slate-400\"></i>\n            <span>${p.name_ar}</span>\n          </span>\n        `;\n        container.appendChild(label);\n      });\n\n      updateSelectedPermsCount();\n    }\n\n    function openPermissionModal() {\n      document.getElementById('permissionForm').reset();\n      document.getElementById('permEditId').value = '';\n      document.getElementById('permKey').disabled = false;\n      document.getElementById('permModalTitle').textContent = '\u0625\u0636\u0627\u0641\u0629 \u0635\u0644\u0627\u062D\u064A\u0629 \u062C\u062F\u064A\u062F\u0629 \u0644\u0644\u0646\u0638\u0627\u0645';\n      document.getElementById('permissionModal').classList.remove('hidden');\n    }\n\n    function closePermissionModal() {\n      document.getElementById('permissionModal').classList.add('hidden');\n    }\n\n    async function handlePermissionSubmit(e) {\n      e.preventDefault();\n      const payload = {\n        key: document.getElementById('permKey').value.trim(),\n        name_ar: document.getElementById('permNameAr').value.trim(),\n        module: document.getElementById('permModule').value.trim(),\n        icon: document.getElementById('permIcon').value.trim() || 'fa-shield-halved',\n        description: document.getElementById('permDescription').value.trim() || undefined,\n      };\n\n      try {\n        const res = await fetch(`${API_BASE}/permissions`, {\n          method: 'POST',\n          headers: getHeaders(),\n          body: JSON.stringify(payload),\n        });\n\n        if (res.ok) {\n          showToast('\u062A\u0645\u062A \u0625\u0636\u0627\u0641\u0629 \u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0629 \u0628\u0646\u062C\u0627\u062D \u0625\u0644\u0649 \u0633\u062C\u0644 \u0627\u0644\u0646\u0638\u0627\u0645');\n          closePermissionModal();\n          await loadPermissions();\n        } else {\n          const err = await res.json();\n          showToast(`\u062E\u0637\u0623: ${err.message || '\u0641\u0634\u0644\u062A \u0627\u0644\u0639\u0645\u0644\u064A\u0629'}`, 'error');\n        }\n      } catch (e) {\n        showToast('\u062D\u062F\u062B \u062E\u0637\u0623 \u0623\u062B\u0646\u0627\u0621 \u062D\u0641\u0638 \u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0629', 'error');\n      }\n    }\n\n    function confirmDeletePermission(id, name) {\n      openDeleteModal(\n        `\u062D\u0630\u0641 \u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0629: ${name}`,\n        `\u0647\u0644 \u0623\u0646\u062A \u0645\u062A\u0623\u0643\u062F \u0645\u0646 \u062D\u0630\u0641 \u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0629 \"${name}\" \u0646\u0647\u0627\u0626\u064A\u0627\u064B \u0645\u0646 \u0627\u0644\u0646\u0638\u0627\u0645\u061F`,\n        async () => {\n          try {\n            const res = await fetch(`${API_BASE}/permissions/${id}`, {\n              method: 'DELETE',\n              headers: getHeaders(),\n            });\n            if (res.ok) {\n              showToast(`\u062A\u0645 \u062D\u0630\u0641 \u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0629 \"${name}\" \u0628\u0646\u062C\u0627\u062D`);\n              await loadPermissions();\n            } else {\n              showToast('\u0641\u0634\u0644 \u062D\u0630\u0641 \u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0629', 'error');\n            }\n          } catch (e) {\n            showToast('\u062D\u062F\u062B \u062E\u0637\u0623 \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u062D\u0630\u0641', 'error');\n          }\n        }\n      );\n    }\n\n    function handleStaffRoleChange(role) {\n      const template = ROLE_PERMISSIONS_TEMPLATE[role];\n      const allCheckboxes = document.querySelectorAll('#permissionsChecklistGrid input[type=\"checkbox\"]');\n      allCheckboxes.forEach(cb => {\n        if (template && template.length > 0) {\n          cb.checked = template.includes(cb.value);\n        }\n      });\n      updateSelectedPermsCount();\n    }\n\n    function updateSelectedPermsCount() {\n      const allCheckboxes = document.querySelectorAll('#permissionsChecklistGrid input[type=\"checkbox\"]');\n      let count = 0;\n      allCheckboxes.forEach(cb => {\n        if (cb.checked) count++;\n      });\n      const badge = document.getElementById('perm-selected-count');\n      if (badge) badge.textContent = `${count} / ${allCheckboxes.length}`;\n    }\n\n    function openStaffModal() {\n      document.getElementById('staffForm').reset();\n      document.getElementById('staffEditId').value = '';\n      document.getElementById('staffModalTitle').textContent = '\u0625\u0636\u0627\u0641\u0629 \u0645\u0634\u0631\u0641 \u0648\u062A\u062D\u062F\u064A\u062F \u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0627\u062A';\n      document.getElementById('staffSubmitBtn').textContent = '\u062D\u0641\u0638 \u0627\u0644\u0645\u0634\u0631\u0641';\n      document.getElementById('staffPasswordHint').textContent = '*';\n      document.getElementById('staffPassword').required = true;\n      document.getElementById('staffRole').value = 'ADMIN';\n      document.getElementById('staffIsActive').checked = true;\n      renderPermissionsChecklist(ROLE_PERMISSIONS_TEMPLATE.ADMIN);\n      document.getElementById('staffModal').classList.remove('hidden');\n    }\n\n    function editStaff(id) {\n      const u = staffData.find(item => item.id === id);\n      if (!u) return;\n\n      document.getElementById('staffForm').reset();\n      document.getElementById('staffEditId').value = u.id;\n      document.getElementById('staffName').value = u.full_name;\n      document.getElementById('staffEmail').value = u.email;\n      document.getElementById('staffPassword').value = '';\n      document.getElementById('staffPassword').required = false;\n      document.getElementById('staffPasswordHint').textContent = '(\u0627\u062A\u0631\u0643\u0647 \u0641\u0627\u0631\u063A\u0627\u064B \u0644\u0644\u0625\u0628\u0642\u0627\u0621 \u0639\u0644\u0649 \u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0627\u0644\u062D\u0627\u0644\u064A\u0629)';\n      document.getElementById('staffRole').value = u.role;\n      document.getElementById('staffIsActive').checked = u.is_active;\n\n      const userPerms = (u.permissions && u.permissions.length > 0) ? u.permissions : (ROLE_PERMISSIONS_TEMPLATE[u.role] || []);\n      renderPermissionsChecklist(userPerms);\n\n      document.getElementById('staffModalTitle').textContent = `\u062A\u0639\u062F\u064A\u0644 \u0635\u0644\u0627\u062D\u064A\u0627\u062A \u0627\u0644\u0645\u0634\u0631\u0641: ${u.full_name}`;\n      document.getElementById('staffSubmitBtn').textContent = '\u062D\u0641\u0638 \u0627\u0644\u062A\u0639\u062F\u064A\u0644\u0627\u062A';\n      document.getElementById('staffModal').classList.remove('hidden');\n    }\n\n    function closeStaffModal() {\n      document.getElementById('staffModal').classList.add('hidden');\n    }\n\n    async function handleStaffSubmit(e) {\n      e.preventDefault();\n      const editId = document.getElementById('staffEditId').value;\n      const role = document.getElementById('staffRole').value;\n      const allCheckboxes = document.querySelectorAll('#permissionsChecklistGrid input[type=\"checkbox\"]');\n      const selectedPerms = [];\n      allCheckboxes.forEach(cb => {\n        if (cb.checked) selectedPerms.push(cb.value);\n      });\n\n      const payload = {\n        full_name: document.getElementById('staffName').value.trim(),\n        email: document.getElementById('staffEmail').value.trim(),\n        role: role,\n        permissions: selectedPerms,\n        is_active: document.getElementById('staffIsActive').checked,\n      };\n\n      const passwordVal = document.getElementById('staffPassword').value;\n      if (passwordVal) {\n        payload.password = passwordVal;\n      }\n\n      try {\n        const url = editId ? `${API_BASE}/admin/users/${editId}` : `${API_BASE}/admin/users`;\n        const method = editId ? 'PUT' : 'POST';\n        const res = await fetch(url, {\n          method,\n          headers: getHeaders(),\n          body: JSON.stringify(payload),\n        });\n\n        if (res.ok) {\n          showToast(editId ? '\u062A\u0645 \u062A\u062D\u062F\u064A\u062B \u0635\u0644\u0627\u062D\u064A\u0627\u062A \u0648\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0645\u0634\u0631\u0641 \u0628\u0646\u062C\u0627\u062D' : '\u062A\u0645\u062A \u0625\u0636\u0627\u0641\u0629 \u0627\u0644\u0645\u0634\u0631\u0641 \u0628\u0646\u062C\u0627\u062D');\n          closeStaffModal();\n          loadStaffUsers();\n        } else {\n          const err = await res.json();\n          showToast(`\u062E\u0637\u0623: ${err.message || '\u0641\u0634\u0644\u062A \u0627\u0644\u0639\u0645\u0644\u064A\u0629'}`, 'error');\n        }\n      } catch (e) {\n        showToast('\u062D\u062F\u062B \u062E\u0637\u0623 \u0623\u062B\u0646\u0627\u0621 \u062D\u0641\u0638 \u0627\u0644\u0645\u0634\u0631\u0641', 'error');\n      }\n    }\n\n    function confirmDeleteStaff(id, name) {\n      openDeleteModal(\n        `\u062D\u0630\u0641 \u0627\u0644\u0645\u0634\u0631\u0641: ${name}`,\n        `\u0647\u0644 \u0623\u0646\u062A \u0645\u062A\u0623\u0643\u062F \u0645\u0646 \u0631\u063A\u0628\u062A\u0643 \u0641\u064A \u062D\u0630\u0641 \u0627\u0644\u0645\u0634\u0631\u0641 \"${name}\"\u061F \u0633\u064A\u0641\u0642\u062F \u062D\u0642 \u0627\u0644\u0648\u0635\u0648\u0644 \u0644\u0644\u0648\u062D\u0629 \u0627\u0644\u062A\u062D\u0643\u0645 \u0641\u0648\u0631\u064A\u0627\u064B.`,\n        async () => {\n          try {\n            const res = await fetch(`${API_BASE}/admin/users/${id}`, {\n              method: 'DELETE',\n              headers: getHeaders(),\n            });\n            if (res.ok) {\n              showToast(`\u062A\u0645 \u062D\u0630\u0641 \u0627\u0644\u0645\u0634\u0631\u0641 \"${name}\" \u0628\u0646\u062C\u0627\u062D`);\n              loadStaffUsers();\n            } else {\n              showToast('\u0641\u0634\u0644 \u062D\u0630\u0641 \u0627\u0644\u0645\u0634\u0631\u0641', 'error');\n            }\n          } catch (e) {\n            showToast('\u062D\u062F\u062B \u062E\u0637\u0623 \u0623\u062B\u0646\u0627\u0621 \u0627\u0644\u062D\u0630\u0641', 'error');\n          }\n        }\n      );\n    }\n\n    // App Initialization\n    window.addEventListener('DOMContentLoaded', async () => {\n      const isAuth = await checkAuth();\n      if (isAuth) {\n        loadOverview();\n      }\n    });\n  </script>\n</body>\n</html>\n";
